insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 1, 'ISIALA''s engineer states a capex belief of 150 / 180 / 220 million USD as a 10th percentile, a median and a 90th percentile. What does the 220 claim?', '["220 million USD is the most the engineer believes the project can cost, so the fitted distribution is built to stop exactly there.", "One outcome in ten costs less than 220 million USD, because a 90th percentile counts its fraction down from the expensive end of the range.", "Nine outcomes in ten cost less than 220 million USD, so one in ten costs more, and the fitted triangle runs on past it to 252.3607.", "Half of the outcomes between the median and the top of the range cost less than 220 million USD, which is where the two halves are split."]'::jsonb, 2, 'A 90th percentile leaves a tenth of outcomes above it, so 150 / 180 / 220 already places a fifth of all outcomes outside its own stated numbers, and the fit reaches 252.3607.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 2, 'The breakeven engine used to feed a stated 10th percentile, median and 90th percentile straight in as a triangle''s ends and peak, and on ISIALA''s capex that reads back 164.4914, 182.5834 and 203.2668 where the engineer wrote 150, 180 and 220. What did that do?', '["Made it narrower on both sides, deleting the tenth below 150 and the tenth above 220 and packing that probability inside the stated range.", "Only moved the middle, since 182.5834 against 180 is the whole of the disagreement and the two outer checks follow from it.", "Made it wider on both sides, since a triangle with ends at 150 and 220 spreads its probability further than three percentiles do.", "Shifted the whole belief upward by the mode''s offset while keeping its width, so the tails survive at slightly higher costs."]'::jsonb, 0, 'The endpoints triangle reads a 10th percentile of 164.4914 where the engineer said 150 and a 90th percentile of 203.2668 where the engineer said 220, so it claims more certainty than was stated.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 3, 'A reviewer calls the endpoints reading of a capex belief conservative, because 150 to 220 million USD looks like a wide and careful range. Why is that backwards for a breakeven study?', '["It is conservative, because cutting away the cheap outcomes below 150 raises every sampled cost and so pushes the breakeven price upward.", "The two lost tails cancel on the breakeven, since the cheap tail removed below 150 offsets the costly tail removed above 220 exactly.", "The endpoints reading only touches capex, and the run''s insight names efficiency as the input the breakeven price is most sensitive to.", "The certainty it adds sits on the expensive side, so the high-price tail of the breakeven, where the project fails, shrinks."]'::jsonb, 3, 'Every capex draw that should land above 220 is replaced by one that cannot, and the insight names Total CAPEX and Annual OPEX as the inputs the breakeven is most sensitive to; the fitted capex runs up to 252.3607.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 4, 'ISIALA''s opex belief of 16 / 20 / 26 million USD a year has a shape ratio of 0.400000. What does that ratio tell the fit?', '["The median sits short of halfway, so the long tail runs toward low opex and the fit places the mode above the stated median of 20 to balance it.", "The median sits short of halfway, so the long tail runs toward high opex and the fit puts the mode low, at an m of 0.233597 and a mode of 17.4160.", "The belief is narrow, because the ratio measures how wide the stated range is against its median, so the fitted triangle is drawn in to 0.400000 of its natural width.", "The belief is close enough to symmetric that the fit sets the mode equal to the stated median of 20 and only solves for the two ends."]'::jsonb, 1, 'The shape ratio is (20 - 16) / (26 - 16) = 0.400000; below 0.5 means a long right tail, answered with a mode low in the range, 17.4160 against a median of 20.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 5, 'A reviewer copies ISIALA''s fitted capex mode of 168.6738 million USD into a report as the capex median. What has gone wrong?', '["Nothing of substance, because on a fitted triangle the mode and the median agree once the bisection has converged to four decimals.", "168.6738 is the fitted triangle''s median and 180 its mean, so the report should quote the mean and label it as the central case.", "168.6738 is the fitted mode; the stated median is 180, and a tail of overruns pulls a skewed triangle''s median above its mode.", "The bisection stopped early, since a converged fit would put the mode on the stated median and the gap is the residual it left."]'::jsonb, 2, 'On a skewed belief mode, median and stated number differ: capex has a mode of 168.6738 against a median of 180, and the fit chose that mode in order to return the median of 180.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 6, 'Why can the fit find the triangle''s shape from the stated belief before it knows the triangle''s size?', '["Subtracting two quantiles cancels the origin and dividing two such differences cancels the range, so the shape ratio depends on m alone.", "The engine rescales every belief onto capex''s own units before fitting, so the size is always known in advance and only the shape is left.", "It cannot: m is solved together with the minimum and maximum in one joint search, and the order of the closed-form lines is only cosmetic.", "The shape is fixed at a symmetric triangle with m of 0.5 for every belief, and only the range and origin are ever solved from the stated numbers."]'::jsonb, 0, 'Any triangle is min + range * g(u, m), so the ratio built from g at 0.1, 0.5 and 0.9 depends on m only, which is why multiplying every number in a belief by one factor leaves m unchanged.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 7, 'ISIALA''s narrow opex belief is 16 / 17 / 26 million USD a year, a shape ratio of 0.100000. What does `fitTriangularToPercentiles` do with it?', '["Refuses the belief and asks for a wider 90th percentile before any breakeven price is solved.", "Moves the stated 10th percentile down until the ratio reaches the band, so the median of 17 holds.", "Fits it exactly by placing the mode just below the minimum, which the fit allows when a belief''s median sits close to its 10th percentile.", "Clamps to the band edge of 0.381966, fits 15.1886 / 15.1886 / 31.0000 with `exact` false, and runs on with a note."]'::jsonb, 3, 'No triangle''s shape ratio lies below 0.381966, so the engine uses the most left-skewed triangle there is and says the stated median sits too near the 10th percentile; it does not refuse the belief.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 8, 'For that clamped opex fit of 15.1886 / 15.1886 / 31.0000, which of the stated 16, 17 and 26 does the fitted triangle still pass through?', '["17 and 16, because the fit keeps the median and the 10th percentile and stretches the maximum out to 31.0000 to make room for them.", "16 and 26, because origin and range are solved from the 10th and 90th percentiles; the median lands well above 17.", "All three to four decimals, since `exact` false only records that the shape ratio had to be clamped and not that a point was missed.", "Only the median of 17, because the clamp is applied to the two ends and the median is left free."]'::jsonb, 1, 'The clamped triangle gives up the median: no triangle''s median can sit as close to 16 as 17 does, while the 10th and 90th percentiles still read 16 and 26.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 9, 'A reviewer sees opex entered as 16 / 17 / 26 million USD a year and assumes half of the sampled opex draws cost under 17. What does the clamped fit actually draw?', '["More than half under 17, because the mode sits at the minimum of 15.1886 and a triangle piles its draws around its mode at the cheap end.", "Exactly half under 17, since the clamp moves only the mode and not the median.", "Far fewer than half under 17, so every sampled price carries more opex than the belief stated.", "None under 17, since the clamp raises the fitted minimum to the stated median."]'::jsonb, 2, 'The clamped triangle runs from 15.1886 to 31.0000 and keeps 16 and 26 as its 10th and 90th percentiles, so its median sits well above the stated 17 and the run proceeds on a belief the engineer did not state.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 10, 'The clamped opex fit''s note says mode at the minimum, yet the fit prints m as 0.000001. Why not 0?', '["Below an m of 0.1 all three checks sit on the upper branch and the ratio stops changing with m, so floating point noise decides where bisection stops.", "The engine keeps m off zero on purpose so that the lower branch of the quantile function never divides by a zero width.", "0.000001 is the bisection''s stopping tolerance, reached after its fixed number of halvings from a starting bracket of 0 to 1.", "The fit is not quite at the edge: an m of 0.000001 is a genuine solution lying a hair to the right of the most left-skewed triangle."]'::jsonb, 0, 'Every m in that flat stretch gives exactly the edge ratio 0.381966, so min and mode still agree to four decimals at 15.1886; a matching flat stretch above 0.9 is why exact fits keep m between 0.1 and 0.9.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 11, 'ISIALA''s fitted efficiency maximum is 99.9640 percent. What keeps it under 100?', '["The fit clamps the maximum at 100 percent and sets `exact` to false.", "The sampler rejects any efficiency draw above 100 percent and redraws.", "The engine caps the efficiency fraction before it scales the profile.", "Only the belief, since neither the fit nor the sampler caps efficiency at 100 percent."]'::jsonb, 3, 'Nothing bounds a fitted efficiency above 100 or a fitted minimum below zero; 99.9640 stays under 100 because the belief 85 / 91 / 96 is centred low enough.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 12, 'After the bisection fixes m, the fit computes the range, then the minimum, then the maximum, then the mode. On a wide cost belief, where can a negative capex come from, and what happens to it?', '["Nowhere, because the range line divides by a positive difference, so every fitted value keeps the sign of the stated 10th percentile it came from.", "The minimum, backed out of the stated 10th percentile, and nothing inspects it, so a negative cost would be sampled like any other value.", "The mode line, since min + m * range can dip below zero on a small m, and the fit then refuses the belief with a note in the insight.", "The range line, which the fit clamps at zero whenever the stated spread is too wide, reporting the result with `exact` set to false."]'::jsonb, 1, 'The closed form never checks what it produces: min = the stated 10th percentile less range * g(0.1, m) can fall below zero, and ISIALA avoids it only because its capex minimum is 127.2260.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 13, 'How should a reviewer confirm that ISIALA''s capex fit of 127.2260 / 168.6738 / 252.3607 honours its belief?', '["Check that the mode lies between the stated 10th and 90th percentiles and that the fitted minimum and maximum lie outside them.", "Check that the fitted mode equals the stated median of 180, since an exact fit places its most likely value on the stated middle.", "Read the fitted triangle back through `triInvCDF` at 0.1, 0.5 and 0.9 and compare: it returns 150.0000, 180.0000 and 220.0000.", "Check that the average of the fitted minimum, mode and maximum equals the stated median, which is what `exact` true certifies."]'::jsonb, 2, 'Plenty of triangles put a mode inside the stated range with ends outside it and honour none of the three points; the engine''s own test is the read-back, and it returns the belief to four decimals.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 14, 'Efficiency''s fit has m of 0.599919. A hand check pushes the fitted triangle back through the quantile function at 0.1, 0.5 and 0.9. Which branch does each check use?', '["The lower branch for 0.1 and 0.5, the upper branch for 0.9 alone.", "The lower branch for 0.1 and the upper for 0.5 and 0.9, copying capex''s split.", "Upper for all three, since the long tail runs low.", "The lower branch for all three, as m exceeds a half."]'::jsonb, 0, 'The lower branch serves u up to m, so 0.1 and 0.5 fall below 0.599919 and only 0.9 lies above it; capex, at 0.331225, uses the lower branch for 0.1 only.'),
  ('uncertainty', 'intermediate', 'module', 'm01-percentiles-are-not-endpoints', 15, 'A screen prints ISIALA''s stated capex of 220 million USD under the heading P90. How should that heading read under the course convention?', '["P90 is right, and under the exceedance meaning it marks capex''s low case, since 220 million USD is exceeded in nine outcomes out of ten.", "\"90th percentile of capex\", because capex is an input where more is worse and a P-label belongs to an outcome where more is better.", "P10, because the exceedance meaning flips the engine key for a cost and so turns a stated 90th percentile around.", "Either heading is acceptable, because the engine key and the P-label name the same quantile and the screen merely capitalises the key."]'::jsonb, 1, 'The engine key for 220 is a plain percentile of a parameter; reading it aloud as P90 imports the exceedance meaning, which is exactly the misuse the two P-label options make, since only a tenth of outcomes exceed 220.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 1, 'Iteration 1 of ISIALA''s breakeven run draws capex with u of 0.936239 and returns 226.5205 million USD, above the stated 90th percentile of 220. Why?', '["The upper branch of `triInvCDF` always returns a value above the stated 90th percentile, whatever the draw, because that branch works its way down from the fitted maximum.", "Its u of 0.936239 is above 0.9, and the fitted triangle runs on to 252.3607, so the draw lands between the fitted 90th percentile and the maximum.", "The capex fit is inexact, so 220 is not the fitted triangle''s 90th percentile and a draw near the top can overshoot it without any meaning.", "The sampler adds a small random perturbation to each value after the inverse CDF has been applied, and on this draw the perturbation happened to push capex upward."]'::jsonb, 1, 'The draw is a fraction of outcomes: 0.936239 asks for a value that more than nine outcomes in ten fall below, and the capex fit is exact, so its 90th percentile is 220 and 226.5205 correctly sits above it.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 2, 'Iteration 1''s opex draw of 0.826447 takes the upper branch, yet the sampled 24.4593 million USD sits below the stated 90th percentile of 26. How do both hold?', '["The upper branch works down from the maximum, so every draw that takes it must land below the stated 90th percentile of the belief.", "Opex was clamped by the fit, so its upper branch is compressed and cannot reach the stated 90th percentile of 26 on any draw at all.", "The branch was chosen against efficiency''s F(mode) of 0.599919 rather than opex''s own, so the value came from the wrong side of the mode.", "The draw is above F(mode) of 0.233597 but below 0.9, so it lands between the mode and the fitted 90th percentile."]'::jsonb, 3, 'The branch only says which side of the mode 17.4160 the draw landed on; whether a value passes the stated 26 depends on whether u passes 0.9, and 0.826447 does not.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 3, 'A hand check applies the lower formula, `a + sqrt(u * (b - a) * (c - a))`, to every draw. What does that do to capex''s first draw of 0.936239 and draws like it?', '["Past F(mode) it always returns less than the true value, pulling every upper-branch draw toward the middle and shrinking the expensive tail.", "Nothing, because the two branches meet at the mode and describe one smooth curve, so either formula serves every draw equally well.", "It returns values beyond the fitted maximum of 252.3607 and so inflates the expensive tail rather than shrinking it.", "It only changes efficiency, since capex and opex are fitted with their modes low in the range and so rarely reach the upper branch."]'::jsonb, 0, 'The lower formula is valid only up to F(mode), 0.331225 for capex; applied past it, the draw of 0.936239 comes out below 226.5205, which is the endpoints error arriving by another door.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 4, '`mulberry32(20260829)` gives the draws 0.936239, 0.826447, 0.952306, 0.732031, 0.064278 and 0.391443. Which draw is iteration 2''s capex?', '["The second, 0.826447, because draw k belongs to iteration k and iteration 2 therefore opens on the second number the generator returns.", "The fifth, 0.064278, because after the first iteration the engine rotates the variables and takes capex second in each later one.", "The fourth, 0.732031.", "None of the six, because every iteration reseeds its own generator from the run seed plus the iteration number before drawing."]'::jsonb, 2, 'Each iteration takes three draws in the fixed order capex, opex, efficiency, so iteration 1 owns draws 1 to 3 and iteration 2''s capex is draw 4, 0.732031, above capex''s F(mode) of 0.331225.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 5, 'Iteration 2''s opex takes the draw 0.064278 against opex''s F(mode) of 0.233597. Where does its sampled value land?', '["On the lower branch, between the stated 10th percentile of 16 and the mode of 17.4160, since no draw can fall below a stated percentile.", "On the lower branch, between the fitted minimum of 13.3201 and the stated 10th percentile of 16, because 0.064278 is below both 0.233597 and 0.1.", "On the upper branch, since opex''s long tail runs toward high values and the upper branch is the one that serves a long tail.", "Nowhere: a draw below 0.1 falls outside the stated belief, so the engine discards it and asks the generator for a fresh one."]'::jsonb, 1, '0.064278 is below F(mode), so the lower branch climbs from the minimum 13.3201 toward the mode 17.4160, and because the draw is below 0.1 the value also sits below the stated 16.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 6, 'In a breakeven Monte Carlo, iteration 40 cannot break even below 500 USD/bbl and is excluded. What happens to the draws of the iteration that follows it?', '["They shift back by three positions, since the excluded iteration returns its unused draws to the generator for the next iteration to take.", "Iteration 40 is run again on fresh draws until it breaks even, so the next iteration starts later in the stream than it otherwise would have.", "The generator skips one draw as a marker of the exclusion, so every later iteration''s capex, opex and efficiency slide one place along.", "Nothing, because iteration 40 consumed its three draws before its solve came back empty."]'::jsonb, 3, 'An excluded iteration never shifts the draws of the ones after it, so a reviewer who drops it from the count slides every later iteration onto the wrong draws; ISIALA''s run of 5000 excludes 0.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 7, 'An analyst rearranges the order in which capex, opex and efficiency appear on the Analyzer''s input screen and reruns at seed 20260829. What changes?', '["Nothing, because the engine finds the three variables by name and draws them in a fixed order.", "Every sampled value, because draws are handed out in the order the variables arrive, so capex may now take opex''s draw in each iteration.", "Only efficiency, because it is drawn last in each iteration and so is the one variable whose position depends on the list that precedes it.", "Only the percentiles, as the sample is sorted in the entry order."]'::jsonb, 0, 'The order capex, opex, efficiency is fixed inside the engine, so the run still reports a median of 73.3297; only a change to the engine that added or swapped a draw would move every value at the same seed.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 8, 'ISIALA''s median breakeven price over 5000 iterations is 73.3297 USD/bbl at the default seed and 72.8475 at seed 7. Which should a report quote?', '["73.3297, because the default seed is the one the engine was calibrated at, and the insight''s reproducibility sentence certifies that result.", "72.8475, because the lower of two breakeven prices is the conservative figure to put before a board deciding whether to sanction.", "Neither alone: both are samples of one distribution, and the honest reading is the spread across seeds, 72.6338 to 73.1287 over seeds 1 to 10.", "The mean of the two, because a second seed halves the sampling error and brings the median to a precision the four decimals can carry."]'::jsonb, 2, 'Picking whichever reads better, now with a seed to prove it reproduces, is seed shopping; the default seed''s 73.3297 even sits above every one of the ten medians from seeds 1 to 10.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 9, 'A reviewer reruns ISIALA''s breakeven at seed 20260829 and gets 73.3297 USD/bbl again, agreeing to four decimals. What has the rerun proved?', '["That 73.3297 is the median of the breakeven distribution to four decimals, since a sampling error would have shown up as a different value.", "That 5000 iterations is enough for the median to converge, since an unconverged sample could not repeat.", "That the generator is cryptographically strong, because a weak generator would drift between runs and fail to match to four decimals.", "That the inputs, the iteration count and the code did not change, and nothing about how close 73.3297 is to the true median."]'::jsonb, 3, 'A seed buys reproducibility, not accuracy: two runs at 20260829 give identical samples by construction, yet across seeds 1 to 10 the medians span 72.6338 to 73.1287 and 73.3297 lies outside them.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 10, 'Across seeds 1 to 10 at 5000 iterations, ISIALA''s median breakeven price runs from 72.6338 to 73.1287 USD/bbl. How many decimals of the default seed''s 73.3297 should a report trust?', '["All four, since the same seed reproduces each one exactly.", "Not even the first, because the spread between seeds already moves it.", "Two, since the engine''s insight rounds the median to 73.33 and the insight is written to the precision the sample actually supports.", "Three, since 5000 iterations shrink the error below a cent."]'::jsonb, 1, 'The seed makes every decimal repeatable, but the ten seed medians differ by about half a dollar and the default sits above all of them, so quoting 73.3297 to four decimals claims precision nobody earned.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 11, 'At seed 20260829 ISIALA''s median breakeven price reads 72.9245 USD/bbl at 1000 iterations, 73.3297 at 5000 and 73.0302 at 20000. What does the sequence show?', '["The median does not creep steadily toward one value as iterations grow; each count reads its percentiles off a sample of a different size.", "The median converges from below, and 73.3297 at 5000 is the settled value that 20000 iterations fail to reach only through rounding.", "Each iteration count draws a different stream from the start, because the engine mixes the count into the seed before generating.", "The iteration count does not enter the result once the seed is fixed, so the three medians differ only by the engine''s display rounding."]'::jsonb, 0, 'Reproducible is not accurate: 73.3297 at 5000 is higher than both 72.9245 at 1000 and 73.0302 at 20000, and every one of them reruns identically at that seed.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 12, 'What do ISIALA''s 20000 iteration run and its 5000 iteration run at seed 20260829 have in common?', '["Nothing beyond the inputs, since the count is mixed into the seed.", "Their three percentiles, since the seed alone fixes them.", "The first 5000 iterations, draw for draw.", "The same set of sampled values in a shuffled order, since the generator permutes the stream according to how many iterations are asked for."]'::jsonb, 2, 'The longer run begins with exactly the shorter run''s iterations and then adds more, so only the sorted positions move: the median is 73.3297 at 5000 and 73.0302 at 20000.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 13, 'An analyst wants to hold ISIALA''s capex draws fixed at seed 20260829 while letting opex vary across runs. Can the seed do that?', '["Yes, because each variable draws from its own stream seeded from the run seed, so changing only the opex stream leaves capex''s draws alone.", "Yes, by entering opex''s belief with a different seed on its own row, which the Analyzer accepts for each uncertain input separately.", "Yes, below 500 iterations, where each variable gets its own generator.", "No: the three variables take turns on one stream, so a seed fixes the whole run."]'::jsonb, 3, '`mulberry32` is a single stream: capex, opex and efficiency take draws 1, 2 and 3 of each iteration from the same sequence that starts at 20260829, so no one variable can be held still.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 14, 'Two runs of ISIALA''s breakeven are both at seed 20260829 and still give different samples. Which difference explains it?', '["Nothing can, because the generator ignores every input except the seed, so two runs at one seed produce identical samples whatever else changes.", "Anything else that differs, such as the beliefs, the production profile, royalty, tax, the discount rate, the target NPV or the iteration count.", "The machine, because `mulberry32` depends on the platform''s floating point, so two computers walk different paths from the same seed.", "The clock, because the generator mixes the start time into its state on the first call so that each run is distinguishable in the log."]'::jsonb, 1, 'The seed fixes the draws and not what they are turned into: 0.936239 becomes 226.5205 only through the fitted capex triangle, and nothing about the clock or the machine enters.'),
  ('uncertainty', 'intermediate', 'module', 'm02-sampling-a-distribution', 15, 'ISIALA''s insight ends "Run seed 20260829: the same inputs and seed reproduce this result exactly." What does that sentence say at 100 iterations?', '["A small-sample warning appended below 500.", "An estimate of how far the median may wander.", "The same words, with no warning about the sample size.", "Nothing, because the engine withholds the reproducibility sentence until a run is long enough for its percentiles to be stable."]'::jsonb, 2, 'The seed refuses to report its own wobble: at 100 iterations the median is 72.7058 against 73.3297 at 5000, and the sentence reads identically for both.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 1, 'Through the breakeven engine ISIALA''s NPV runs from -220.0581 million USD at 20 USD/bbl to 311.7558 at 150. Why can a higher price never lower that NPV?', '["The breakeven engine switches tax off while it solves, so each extra dollar of price reaches the net cash flow whole in every producing year.", "It can: above the price where a year''s tax switches on, the tax taken exceeds the revenue added, and the curve turns down for a stretch.", "The engine sorts the priced points before bisecting, which forces the curve to rise whatever the underlying cash flows would have done.", "Royalty and tax each take only part of the extra revenue, costs do not depend on price, and every discount factor is positive."]'::jsonb, 3, 'Royalty takes 15 percent of an increase off the top and tax 35 percent of what is left in a taxed year, so each year keeps part of every extra dollar and the sum rises; NPV crosses zero at 71.6277.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 2, 'Each dollar of oil price between 20 and 40 USD/bbl adds more to ISIALA''s NPV than each dollar between 100 and 150. Why?', '["At low prices most years pay no tax and keep more of each extra dollar, and each year that starts paying tax makes the line shallower.", "Discounting weighs the cash of a low price more heavily than the cash of a high one, since the factors fall as the price rises.", "Royalty is charged on a scale that climbs with price, so a larger share of each dollar is taken off the top at 100 than at 20.", "Production responds to price in the breakeven case, so volume grows fastest while the price is still low and then levels off."]'::jsonb, 0, 'The slope falls at every kink: at the breakeven 71.6277 only years 2 to 12 pay tax, while at 150 more years hand over 35 percent of their extra revenue after royalty.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 3, 'ISIALA''s quick-form screening NPV at 70 USD/bbl is 81.0464 million USD, while the breakeven engine''s NPV at the same 70 USD/bbl is -6.5653. What reconciles them?', '["One engine is wrong, because an NPV of 81.0464 at 70 USD/bbl means the breakeven price of the same field must sit well below 70.", "The breakeven engine discounts at year end while the screening engine discounts mid-year, and the convention alone moves NPV that far.", "They price different cases: the breakeven case puts all 180 of capex in year 1, charges a flat 20 of opex with no variable opex, and sells 0.91 of the volume.", "The breakeven engine subtracts a default target NPV before reporting, so its -6.5653 is the shortfall against that hurdle and not an NPV."]'::jsonb, 2, 'Each engine is right about the case it built; the quick form splits capex 50/50 and charges 2.5 fixed plus 13 USD/bbl variable, which is why 81.0464 and -6.5653 do not contradict each other.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 4, '`solveBreakevenPrice` checks ISIALA at the top of its bracket, where NPV reads 1552.6414 million USD, and then takes the first midpoint. What happens at 250 USD/bbl?', '["NPV there is below the 1552.6414 read at the top, so 250 becomes the low end and the search moves up toward 500.", "NPV there is positive against a target of 0, so 250 becomes the high end of the bracket.", "The solver starts from ISIALA''s own 70 USD/bbl rather than the midpoint and takes Newton steps from there toward the root.", "The midpoint is compared with the previous midpoint rather than the target, and the one with the smaller NPV is discarded."]'::jsonb, 1, 'Each step compares the midpoint''s NPV with the target: NPV is already 311.7558 at 150 and only rises with price, so 250 is above the answer and the bracket closes onto 71.6277.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 5, 'Why does the breakeven engine search by bisection rather than Newton''s method?', '["NPV jumps at each kink where a year''s tax switches on, and a jump can only be crossed by a method that never evaluates a slope.", "Bisection needs fewer NPV evaluations than Newton''s method, and each evaluation is a full twenty year ledger that is slow to build.", "Newton''s method cannot work with a negative NPV, and every bracket in the breakeven engine starts from a price where NPV is below zero.", "The slope of NPV against price changes abruptly at every kink, and bisection needs only a rising NPV and an answer inside the bracket."]'::jsonb, 3, 'The curve bends at a kink and never jumps, so every halving keeps the answer inside; bisection spends more evaluations than a cleverer method and is never wrong about the side, reaching 71.6277 on ISIALA.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 6, 'A straight line through ISIALA''s NPV of -6.5653 at 70 USD/bbl and 33.6477 at 80 crosses zero slightly above the solved 71.6277. What accounts for the gap?', '["Year 13''s tax switches on at 74.6504, inside that interval, and below that kink the NPV climbs more steeply, so the true crossing comes earlier.", "The solver stops a fixed number of halvings short of the root and reports the middle of a bracket that is still wide enough to show.", "The straight line is right and the solver is wrong, since between two tabulated prices the NPV of a screening case is exactly linear.", "Mid-year discounting bends the curve upward between every pair of prices, so any chord through two points lies below the true curve."]'::jsonb, 0, 'NPV is a straight line only between kinks; 74.6504 splits the interval from 70 to 80, so the chord through the two tabulated points is not the curve and the gap is not an engine error.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 7, 'ISIALA''s breakeven of 71.6277 USD/bbl sits between the 2038 kink of 65.6923 and the 2039 kink of 74.6504. Which years pay tax at that price?', '["Years 1 to 12, since year 1 carries the most production of the profile and its revenue is taxed before any other year''s.", "Years 2 to 12; year 1 and years 13 to 20 do not.", "Years 13 to 20, since a year pays tax once the price has not yet reached its kink and those kinks all lie above the breakeven.", "All twenty years, since the breakeven price is by definition the price at which every year''s taxable income reaches zero at once."]'::jsonb, 1, 'A year pays tax once the price passes its own kink: 2028 to 2038 sit below 71.6277, while 2027 at 160.9994 and 2039 onward from 74.6504 sit above it.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 8, 'ISIALA''s 2027 kink is 160.9994 USD/bbl and its 2028 kink is 18.2954. Why is the first year''s so much higher?', '["Production in 2027 is the smallest of the profile, since the field ramps up before it declines, so year 1 needs the highest price to cover its opex.", "The quick form''s 50/50 split puts half of capex in each of the first two years.", "All 180 million USD of capex is expensed in year 1, where it joins opex in the numerator.", "Year 1 is discounted by only half a year, so its threshold is higher."]'::jsonb, 2, 'The kink is (opex + capex expensed that year) / ((1 - royalty) x volume x efficiency) x 1e6; from 2028 the numerator is opex alone, which is why the kinks then climb with the decline to 182.6642.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 9, 'ISIALA at the stated medians expenses its 180 million USD of capex in year 1. What becomes of that deduction at a price below 160.9994 USD/bbl?', '["It carries into 2028 and shelters that year''s income first, which is why the 2028 kink is so low.", "It is refunded at the tax rate of 35 percent as a negative tax payment, so the deduction is worth the same at any price the solver tries.", "The engine spreads it evenly over all twenty years whenever year 1 cannot absorb it, moving every later kink upward by the same step.", "The part with no year 1 income to shelter is lost, so an engine with a loss carry-forward would report a lower breakeven."]'::jsonb, 3, 'The breakeven engine carries no loss forward, so the capex deduction is worth 35 percent of 180 only when the price reaches 160.9994; the 2028 kink of 18.2954 is opex alone.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 10, 'A breakeven case would reach its target NPV only at a price just above 500 USD/bbl. What does `solveBreakevenPrice` return?', '["500, the top of the bracket, with a flag in the result noting that the solve stopped at the edge of its search range.", "Null, exactly as it does for a case that never breaks even at any price.", "The true price above 500, found by doubling the bracket once.", "0.0000, because the bracket collapses onto its low end."]'::jsonb, 1, 'The solver prices 500 first and returns null if NPV there is below the target; it refuses to widen the bracket, so solve_unreachable''s target of 500000 and a near miss look the same.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 11, 'The published mc_with_unreachable run excludes 55 of 120 iterations and reports a 10th percentile of 397.3404, a median of 449.5729 and a 90th percentile of 486.6757, beside a base case of 498.0372. How are those percentiles biased?', '["Downward, because every excluded iteration needed a price above 500 and removing them drags the reported distribution down.", "Upward, because the engine stacks each excluded iteration at 500 USD/bbl and those piled values lift every percentile read above them.", "Not at all, because the excluded iterations are a random subset of the draws and so leave the shape of the surviving sample unchanged.", "Not at all, since a base case above the 90th percentile shows the base solve is at fault."]'::jsonb, 0, 'Each excluded iteration sits beyond every survivor, so counted back in the median would land among the most expensive survivors and the 90th percentile among the excluded; the base of 498.0372 above 486.6757 is the tell.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 12, '`solve_free_project_zero` returns 0.0000 and `solve_zero_production_null` returns null. A spreadsheet imports both and turns null into 0. What has it done?', '["Unified two spellings of one answer, harmlessly.", "Correctly flagged two failures of the search.", "Kept both as unreachable, as the golden intends.", "Read a project that can never break even as one that is free."]'::jsonb, 3, 'The free project has NPV already non-negative at 0 USD/bbl, so 0.0000 is the correct answer; the zero production case is flat and negative at every price, and null says no price reaches the target.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 13, 'A memo says ISIALA breaks even at 96.5968 USD/bbl. The engine returns that price for a target NPV of 100 million USD. What has the memo done?', '["Reported the breakeven at a discount rate raised above 12 percent far enough to cover the hurdle.", "Reported the price that recovers an extra 100 million USD of capex spent in year 1.", "Quietly demanded 100 million USD of present value on top of earning 12 percent; the plain breakeven is 71.6277.", "Nothing wrong, since any target NPV the solver meets is a breakeven and 100 million USD is only the Analyzer''s default hurdle setting."]'::jsonb, 2, 'A target NPV above zero asks for a stated sum beyond the discount rate, so 96.5968 is a hurdle price; a target of 250 takes 134.3869, and only a target of 0 gives the breakeven.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 14, 'Why is a target NPV of 100 million USD on ISIALA not the same thing as raising its discount rate?', '["They are the same, since both raise the breakeven price and the engine converts any target NPV into an equivalent discount rate first.", "A target leaves every discount factor as it is and asks for a fixed sum, while a higher rate weighs the late years less.", "A target is extra capex under another name, discounted with year 1''s spend and taxed there.", "A target scales with project size, so 100 on ISIALA asks for the same return on capital as 100 on the published case with capex of 1000."]'::jsonb, 1, 'At 12 percent a target of 100 moves ISIALA''s price from 71.6277 to 96.5968 without touching a single factor; the target is absolute, so it means something different on a case with capex of 1000.'),
  ('uncertainty', 'intermediate', 'module', 'm03-the-breakeven-price', 15, 'The published mc_seed_7 and mc_target_250_seed_7 runs share seed 7 and 300 iterations and differ only in the target, 0 against 250. Their medians are 179.2190 and 214.9766. Why is that comparison fair?', '["The shared seed gives every iteration the same sampled capex, opex and efficiency in both runs, so only the target moved each price.", "Both runs were given 300 iterations, which is enough on its own for any two medians to converge whatever seed each happens to use.", "The target of 250 is subtracted from each iteration''s NPV after sampling, so the second run is just the first shifted by a fixed price.", "The seed resets between the two targets, so the second run draws a fresh and independent sample that averages out the sampling error of the first run."]'::jsonb, 0, 'Same seed, same draws: with the belief sampled identically, every iteration''s price rises with the hurdle, and the base case moves the same way from 175.1500 to 210.4257.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 1, 'ISIALA''s breakeven run sorts 5000 prices. At which sorted index, counting from zero, does the breakeven engine read the 90th percentile of breakeven price, and how is the value formed?', '["Index 4500 averaged with its lower neighbour, because the count times nine tenths is a whole number on an even length and the rule splits the difference.", "Index 4500, taken as that one sorted price with no averaging, so 85.5912 is a price one iteration actually produced.", "The dearest 500 prices averaged together, so 85.5912 is the mean breakeven of the most expensive tenth of the sample.", "The price nine tenths of the way between the lowest and the highest breakeven, interpolated along the sorted list."]'::jsonb, 1, 'The engine reads sorted[min(n - 1, floor(q n))]: floor of 0.9 times 5000 is 4500, and floor means no averaging and no interpolation.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 2, 'In the breakeven engine''s rule sorted[min(n - 1, floor(q n))], what does the min(n - 1, ...) guard protect against?', '["A q of zero, which would ask for the index before the first value and read memory ahead of the sorted list.", "Excluded iterations, where n would still count the 55 dropped prices on mc_with_unreachable and index past the survivors.", "An empty sample, which the guard maps to the last stored price instead of throwing when no iteration breaks even.", "A q of one, which would ask for index n, one step past the last value of a list counted from zero."]'::jsonb, 3, 'The list runs from index 0 to n - 1, so only the top end can overrun; an empty sample is handled by a thrown error, not by this guard.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 3, 'ISIALA''s sorted breakeven sample runs from 50.7415 to 107.6755 USD per bbl. Why does the lesson quote 62.1713 and 85.5912 as the range to carry instead of those two ends?', '["Each end is a single iteration, one combination of three draws, while the 10th and 90th percentiles each have hundreds of prices on their outer side.", "The two ends are the fitted triangles'' minimum and maximum pushed through the solve, so they describe the fit rather than the sample.", "The ends are clipped by the 0 to 500 USD per bbl bracket, so neither is a real solve and the engine discards both before any of the percentiles are read.", "The ends move with the seed while the percentiles are fixed by the fitted triangles, so only the percentiles can be reproduced."]'::jsonb, 0, 'Nothing in the sample supports 50.7415 or 107.6755 beyond the one iteration that produced it, and the percentiles move with the seed too.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 4, 'A reader wants to know whether the price at sorted index 4500 on ISIALA''s run came from high capex, high opex or low efficiency. Where does that question get answered?', '["In the draws stored beside each sorted price, which the sort carries along so every percentile can be traced back to its capex, opex and efficiency.", "In the draw order, since capex is drawn first and so sets the rank of every price in the sorted list.", "Not in the sorted list, which keeps the prices and discards the draws; which input drives the price belongs to the tornado, a separate calculation at the stated percentiles.", "In the S-curve, whose steep middle is shaded by the input that dominated each iteration''s breakeven."]'::jsonb, 2, 'Sorting keeps 5000 prices and throws away which draws made them; the tornado never looks at the sample and swings each stated belief from the base of 71.6277.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 5, 'The engine stores ISIALA''s breakeven percentiles under the keys `p10`, `p50` and `p90`. How is the value under `p90`, 85.5912 USD per bbl, read?', '["Nine in ten iterations broke even at or above 85.5912, the exceedance meaning the key''s name carries over from the labels on the NPV panel.", "Nine in ten iterations broke even at or under 85.5912: it is the 90th percentile of breakeven price, a plain cumulative percentile.", "It is the breakeven with capex and opex at their 90th percentiles and efficiency at its 10th, the pessimistic corner solved once.", "It is the oil price the market stays under nine years in ten, since the run samples price alongside the three costs."]'::jsonb, 1, 'The keys mean exactly what they say, plain percentiles; reading `p90` with the exceedance meaning carries the NPV panel''s P-labels onto a price, the misuse here. The engine''s insight reads it as a 90 percent chance the breakeven price is below 85.59.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 6, 'A sanction note carries the NPV panel''s convention onto ISIALA''s breakeven and quotes 62.1713 USD per bbl as the conservative breakeven. What is wrong with it?', '["Nothing, since the value you are fairly sure to beat is the low one, for a breakeven price exactly as for an NPV.", "The conservative breakeven is the base case at the stated medians, 71.6277, the only figure that holds every input at its stated belief at once, with no sampling in it.", "The conservative breakeven is the mean, 73.6242, because only the mean weights the dear iterations a sanction meeting worries about.", "62.1713 is the 10th percentile of breakeven price and the least conservative of the three; the cautious figure is the 90th percentile, 85.5912."]'::jsonb, 3, 'A breakeven is a quantity where more is worse, so an exceedance reading reverses it: one iteration in ten broke even at or under 62.1713, the kindest tenth of the cost beliefs.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 7, 'At the default seed ISIALA''s breakeven percentiles read 61.1861, 72.7058 and 86.3529 at 100 iterations and 62.2724, 73.0302 and 85.4380 at 20000. What does that say about the 5000 iteration figures of 62.1713, 73.3297 and 85.5912?', '["They are exact to four decimals, because a fixed seed removes sampling error and the other counts differ only by rounding.", "They carry an oil price uncertainty the 100 iteration run lacked, which is why its 10th to 90th percentile spread is the wider one.", "They are estimates from one sample: the seed pins them so a rerun repeats them, without making them exact.", "They must be replaced by the 20000 iteration figures, since any count below the largest one misreports the belief and is void."]'::jsonb, 2, 'The same seed repeats a sample, and a different count is a different sample: the median moves from 72.7058 to 73.3297 to 73.0302 across the three counts.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 8, 'ISIALA''s run prints a mean breakeven of 73.6242 above its median of 73.3297, while mc_with_unreachable prints a mean of 446.8432 under its median of 449.5729. What reverses the order?', '["ISIALA''s longer tail runs right from cost triangles with a long upper reach, while mc_with_unreachable''s expensive tail was cut off at the 500 USD per bbl bracket.", "ISIALA draws at seed 20260829 and mc_with_unreachable at seed 5, and which centre sits higher is decided by the seed.", "ISIALA''s median uses the floor rule while mc_with_unreachable''s averages two neighbours on its count of survivors.", "Finding B1 prints mc_with_unreachable''s two centres in the wrong order, the same defect that zeroes its tornado."]'::jsonb, 0, 'A mean past the median signals a longer right tail: ISIALA''s capex triangle reaches 252.3607; on mc_with_unreachable the dear iterations were excluded, 55 of 120.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 9, 'On ISIALA''s S-curve the point at sorted index 2500 sits at 73.3297 with a height of 0.500200. Why is the height not a round half?', '["Excluded iterations shrink n below 5000, so every height is divided by the survivors and drifts just above the round value.", "The curve places index i at (i + 1) / n while the percentile rule takes index floor(q n), two conventions a step apart.", "The median is averaged from two neighbours and the curve plots the upper of the pair, which lifts the height by one step.", "The curve is downsampled to 50 points and 0.500200 is simply the kept height that lies nearest to a half."]'::jsonb, 1, 'ISIALA excluded 0 iterations and the breakeven S-curve draws every sorted price; (2500 + 1) / 5000 gives 0.500200, a disagreement that is only a convention.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 10, 'A reader turns ISIALA''s breakeven S-curve upside down and reads it as an exceedance curve. What does that do to 85.5912 USD per bbl?', '["Nothing of substance, since a cumulative curve and its exceedance mirror carry the same three prices under different labels.", "It moves 85.5912 to the height of the median, because the mirror folds the curve about its half and swaps the two tails before any price is read off it.", "It stretches the right tail, so 85.5912 slides up towards the highest price of 107.6755 at the same height.", "It makes 85.5912 a price the breakeven exceeds nine times in ten, the opposite of the run, where nine in ten iterations broke even at or under it."]'::jsonb, 3, 'The height is the probability of a breakeven at or under the price; flipped, the curve reports 85.5912 as met or exceeded nine times in ten, which the run refutes.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 11, 'ISIALA''s breakeven S-curve reads zero under 50.7415 and one past 107.6755 USD per bbl. What do those flat ends establish?', '["That the fitted triangles bound the breakeven between those two prices, since no draw can come from beyond a triangle''s minimum or maximum.", "That the bisection bracket was narrowed to that span for the run, so any breakeven outside it would be refused as unreachable.", "Only what was sampled: these draws did not reach further, and nothing says ISIALA''s breakeven cannot fall outside that span.", "That the run has converged, because a curve that flattens on both sides has sampled both of its tails completely."]'::jsonb, 2, 'Each end is one iteration''s price; the fitted maxima of 252.3607 for capex and 30.8541 for opex were not drawn together, so dearer combinations remain possible.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 12, 'On the published mc_with_unreachable run the base case at the stated medians breaks even at 498.0372, higher than the reported 90th percentile of breakeven price, 486.6757. What puts the base above the top percentile?', '["55 of the 120 iterations never broke even under 500 USD per bbl and were excluded; they were the expensive draws, so the percentiles describe the cheaper survivors.", "The base case is solved at the fitted modes while the sample draws from the triangles, and on this case the modes sit above the stated medians.", "The base case is solved inside a wider bracket than the sample, so it finds a breakeven that no iteration can reach under 500.", "Its mean of 446.8432 sits under the median, and that left skew drags the whole percentile table below the base."]'::jsonb, 0, 'Only the excluded count reveals it: on ISIALA''s complete sample the base of 71.6277 sits between the 10th percentile and the median, where a centre belongs.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 13, 'Put the 55 excluded iterations of mc_with_unreachable back into its sample. Where does the median of the whole sample lie against the reported 449.5729 USD per bbl?', '["Unchanged, because the engine already placed the excluded iterations at the 500 USD per bbl bracket top before sorting.", "Lower, since the excluded iterations are the ones that lost money at every price and would be sorted in at a breakeven of zero.", "At the base case of 498.0372, which the engine prints so that a reader can recover the median of the full sample.", "Higher, because every excluded iteration would sit past every survivor and push the middle of the list up."]'::jsonb, 3, 'The 55 excluded iterations are placed nowhere and nothing substitutes 500 for them; they are the dear draws, so restoring them moves the median up.'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 14, 'On the published mc_all_unreachable_throws case no iteration breaks even below 500 USD per bbl. What does the breakeven engine return?', '["Percentiles of 500 USD per bbl at every row, since the bracket top is substituted for each missing price and flagged in the insight.", "It throws an error naming the problem and the inputs to check, rather than reporting percentiles of an empty sample.", "A widened bracket, doubled until at least one iteration crosses, with the new top printed beside the excluded count.", "Null at every percentile, with the excluded count equal to the iteration count and the tornado still solved at the base."]'::jsonb, 1, 'Exclusion refuses to guess, with no wider bracket and no 500 substituted: "No iteration broke even below 500 dollars a barrel. Check the production profile, the cost ranges and the target NPV."'),
  ('uncertainty', 'intermediate', 'module', 'm04-reading-the-sample', 15, 'ISIALA''s run gives a median breakeven of 73.3297 and a mean of 73.6242, and the base case at the stated medians gives 71.6277. Why does the base sit under both?', '["The breakeven is no straight line in its inputs, with efficiency scaling the barrels and tax switching on at yearly kinks, so skewed triangles move the centre of the output away from the output at the centre.", "The base case is solved at the fitted modes of 168.6738 for capex and 17.4160 for opex, which sit under the stated medians and price a cheaper project.", "The base case is drawn at a different seed from the run, and at 5000 iterations a different seed shifts the median down by about two dollars.", "The base case is itself a percentile of the sample, read at a lower sorted index than the median, which is why it moves with the seed."]'::jsonb, 0, 'The base is one solve at capex 180, opex 20 and efficiency 0.91 and prints the same number at any seed; mc_default_seed_300 shows the same order, base 175.1500, median 178.1754, mean 180.0854.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 1, 'ISIALA''s Total CAPEX bar reads a high side of 9.4067. What is that number?', '["A breakeven price in its own right, the oil price at which ISIALA breaks even when capex sits at its 90th percentile and the other two inputs sit at their medians.", "A distance from the sample median of 73.3297, since the tornado anchors each bar where the centre of the run lies rather than at a single deterministic solve.", "A distance in USD per bbl from the base breakeven of 71.6277, the move capex at its 90th percentile of 220 makes with the other inputs at their medians.", "A change in NPV in million USD when capex moves from 180 to 220 at a fixed oil price of 70 USD per bbl."]'::jsonb, 2, 'Every low side and high side is measured from the base at the stated medians; quoting 9.4067 as a price, or measuring it from 73.3297, mixes two anchors.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 2, 'ISIALA''s fitted triangles have modes of 168.6738 for capex, 17.4160 for opex and 92.0352 for efficiency. Which values does the tornado''s base case use?', '["The stated medians, capex 180, opex 20 and efficiency 0.91, and none of the fitted modes.", "The fitted modes, since a mode is the triangle''s most likely value and the base case is meant to be the likeliest project.", "The medians recomputed from the fitted triangles, which the engine derives afresh before the base case is solved.", "The first iteration''s draws of 226.5205, 24.4593 and 97.2265, so that the base case shares the seed with the run."]'::jsonb, 0, 'The engine uses the numbers you stated, and bisection to an NPV of zero at 180, 20 and 0.91 gives 71.6277; a base built from the modes solves a different project.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 3, 'ISIALA''s quick screening case earns an NPV of 81.0464 million USD at 70 USD per bbl, yet through the breakeven engine the NPV at 70 is -6.5653 and the breakeven is 71.6277. How are the two reconciled?', '["One of them is a defect, since a field worth 81.0464 million USD at 70 USD per bbl has to break even below 70 on any engine that is computing its ledger correctly.", "They differ only in discounting, one engine using mid-year factors and the other year end, and the gap closes once one NPV is converted into the other''s convention.", "The screening NPV is a Monte Carlo statistic and the breakeven engine''s NPV a single solve, so one describes a sample and the other one draw from it.", "Both are right because they are different cases: the quick form splits capex 50/50 and charges fixed and variable opex, while the Breakeven Analyzer puts all capex in year 1, holds opex flat at 20 and scales production by efficiency."]'::jsonb, 3, 'The two numbers come from two cases and are not a contradiction, so 71.6277 says nothing about the price at which the screening NPV of 81.0464 falls to zero.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 4, 'A note quotes ISIALA''s capex bar as plus or minus half of its 16.4269 swing. What does that lose?', '["Nothing, because the swing is defined as twice the distance from the base to either end, so the two halves are equal by construction.", "The lean of the bar: the low side is -7.0202 and the high side 9.4067, so a symmetric figure puts the low end too low and the high end too short.", "The anchor, since half the swing is measured from the sample median while each side of the bar is measured from the base breakeven at the stated medians.", "The sign of the capex effect, which a plus or minus conceals on a bar where the dearer capex lowers the breakeven price."]'::jsonb, 1, 'The swing is high side minus low side, and capex''s 220 sits further from 180 than 150 does, so the overrun hurts more than the saving helps.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 5, 'Capex''s fitted triangle on ISIALA runs from 127.2260 to 252.3607. Where do those two ends enter ISIALA''s tornado?', '["Nowhere: the bar swings between the stated 10th and 90th percentiles, 150 and 220, and the fitted ends exist only to pass a triangle through three points.", "As the two ends of the bar, since the tornado swings each input across the full reach of its fitted triangle.", "In the base case, which averages the fitted minimum, mode and maximum before the bisection starts.", "As a clip on each side, capping the bar wherever a stated percentile falls outside the fitted range."]'::jsonb, 0, 'The stated 10th and 90th percentiles are the belief; swinging to 127.2260 and 252.3607 would stretch every bar.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 6, 'Replace ISIALA''s opex belief with the narrow 16 / 17 / 26. The base breakeven moves to 67.2301 and the opex bar reads a low side of -1.4602 and a high side of 13.2707. Why is the high side so much longer?', '["The fit clamped to 15.1886 / 15.1886 / 31.0000, and the tornado swings a clamped belief to its fitted maximum of 31.0000 on the high side instead of the stated 26.", "The bar is measured from the sample median, which the clamped triangle pushed up, so the high side starts from a higher centre than the stated one of the run.", "The stated median of 17 sits just past the 10th percentile of 16, so the step down barely moves the price while the reach up to 26 moves it a great deal.", "Every side is scaled by the base breakeven, and a base that fell to 67.2301 stretches the high side in proportion."]'::jsonb, 2, 'The base and the tornado run at the stated median of 17 and swing to the stated 16 and 26; the clamped triangle feeds only the sample, finding EC3-5.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 7, 'On the published mc_with_unreachable case the tornado''s low sides read -80.7218, -6.7689 and -26.2125, and every high side reads 0.0000. What swing does the engine give each bar, and what does the sort then do?', '["A swing equal to each low side''s size, 80.7218 for capex, so capex still ranks first and only the drawing of the high side is lost.", "No swing and no bars, because the engine drops a variable from the tornado once either of its sides fails to break even under 500 USD per bbl, leaving an empty chart.", "A swing measured to the bracket top instead, since a high side that cannot be solved is placed at 500 USD per bbl before the sort.", "A swing of 0 for every bar, because a missing side zeroes the swing, so the sort ranks nothing and a bar with a missing side sorts last whatever its influence."]'::jsonb, 3, 'The base of 498.0372 sits just short of the bracket top, so no high side is solved; finding B1 is not repaired, and a zero looks exactly like a variable that does not matter.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 8, 'ISIALA''s efficiency bar reads a low side of -3.7306 and a high side of 5.0561. Which efficiency stands behind the high side?', '["The 90th percentile of efficiency, 96 percent, since the high side of every bar comes from the input''s 90th percentile.", "The 10th percentile of efficiency, 85 percent, because fewer barrels under the same cost need a higher price.", "The fitted maximum of 99.9640 percent, since efficiency swings to its triangle''s ends while the costs swing to stated percentiles.", "The median of 91 percent with opex moved to its 90th percentile, since efficiency on its own cannot raise the price."]'::jsonb, 1, 'Efficiency runs backwards: its low-price end comes from the 90th percentile efficiency, 96, and its high-price end from the 10th, 85.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 9, 'Where does efficiency sit in the price at which a year''s tax switches on, and what does that do to the direction of its tornado bar?', '["In the numerator beside opex, as the cost of barrels lost, so a higher efficiency raises the price exactly as a higher opex does.", "Nowhere, since efficiency scales the royalty rather than the barrels and moves the price only through the government''s share of revenue in each year of the twenty year profile.", "In the denominator beside the volume, so more efficiency puts more barrels under the same cost and lowers the price, opposite to capex and opex in the numerator.", "In the discount factor, where a higher efficiency brings production forward in time and lowers the price through the timing alone."]'::jsonb, 2, 'The kink is (opex + capex expensed that year) / ((1 - royalty) x volume x efficiency) x 1e6, and ISIALA''s efficiency triangle leans the other way, its mode at 0.599919 of the range.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 10, 'Starting from the published base case of capex 1000, opex 60 and efficiency 0.9, which breaks even at 175.1500, which one-input change lowers the breakeven?', '["Raising opex to 75, since a larger opex shelters more of each year''s income from tax.", "Raising efficiency to 0.95, which spreads the same cost over more barrels.", "Raising capex to 1300, since all of it is expensed in year 1 and the larger deduction removes tax.", "Raising the target NPV to 250 million USD, since a hurdle lets the bisection stop at a lower price."]'::jsonb, 1, 'Efficiency 0.95 gives 165.9316; opex 75 gives 185.3034, capex 1300 gives 215.5109 and a 250 target gives 210.4257, all higher, because a deduction never returns more than the cost it deducts.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 11, 'A sanction note writes "the 90th percentile case" beside the high side of every ISIALA bar. What does that label say on the efficiency bar?', '["That the breakeven rises when the wells perform well, since the efficiency high side of 5.0561 came from the 10th percentile of efficiency, 85 percent.", "Nothing wrong, since low side and high side name the input''s percentiles and the chart follows that one rule on every bar, efficiency included, with no exception.", "That the sample''s 90th percentile of breakeven price sits 5.0561 above the base, reading the side name as a percentile of the run.", "That efficiency outranks capex, since a bar labelled at its 90th percentile is sorted by its high side rather than its swing."]'::jsonb, 0, 'The side names describe the price, not the input; name the input value beside each end, because on this bar the 90th percentile efficiency of 96 gives the low side, -3.7306.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 12, 'On the narrow opex belief 16 / 17 / 26 the bars read Total CAPEX -7.0493 and 9.4442, Annual OPEX -1.4602 and 13.2707, and Prod. Efficiency -3.5016 and 4.7457. Which variable leads a sort by high side, and which trails a sort by low side?', '["Total CAPEX leads both sorts, because it has the largest low side and the largest high side on this belief exactly as on the stated one.", "Annual OPEX leads the sort by high side and Prod. Efficiency trails the sort by low side, because efficiency runs backwards.", "Prod. Efficiency leads the sort by low side since it runs backwards, and Total CAPEX trails the sort by high side.", "Annual OPEX both leads the sort by high side and trails the sort by low side."]'::jsonb, 3, 'Opex has the largest high side, 13.2707, and the smallest low side, -1.4602, so the two one-sided sorts disagree and the swing folds both directions into one width.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 13, 'What would a narrower stated capex belief do to ISIALA''s tornado, with the project itself unchanged?', '["Move capex down the chart without making the project any less exposed to capex, because the swing measures how far the stated 10th and 90th percentiles move the price.", "Nothing, because the tornado ranks inputs by their effect on the project, which a belief about the input cannot change.", "Shorten the capex bar and lower the base breakeven of 71.6277 with it, since the base case is solved at the width of every belief.", "Narrow the bar but keep its rank of 1, since the sort uses the fitted triangle''s reach, which a narrower belief leaves where it was."]'::jsonb, 0, 'The ranking is a ranking of beliefs: capex leads on 150 / 180 / 220 with a swing of 16.4269, and tightening the belief on paper shrinks the bar whether or not the cost became more certain.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 14, 'The screening sensitivity on ISIALA makes OPEX its smallest bar, 85.3696 at 0.7 and 76.7233 at 1.3, while the breakeven tornado ranks Annual OPEX second with a swing of 14.7308. Why do the rankings differ?', '["One of the two charts is defective, since a single field has one true ranking of its inputs and both charts claim to be showing it to the reader.", "The screening bar is in NPV and the tornado in price, and converting the NPV swing at the breakeven would restore the same order on both.", "The screening bar scales fixed opex only, 2.5 million USD a year, and leaves variable opex untouched, while the tornado swings the whole 20 million USD a year across a stated belief.", "The screening chart carries an oil price bar that absorbs opex''s share of the variation, and the breakeven tornado has no such bar."]'::jsonb, 2, 'Different cases, different quantities and different scaling rules, so neither ranking carries across: the screening OPEX swing is -8.6463 million USD on an NPV of 81.0464.'),
  ('uncertainty', 'intermediate', 'module', 'm05-the-two-sided-tornado', 15, 'Why does ISIALA''s breakeven tornado have no oil price bar?', '["Price is held at the quick input of 70 USD per bbl, and an input held fixed gets no bar however much it moves the NPV.", "Price is what the breakeven solves for, so there is no price to swing around the base.", "The price bar would be the widest by far, so the panel draws it on a separate chart to keep the cost bars readable.", "Price is sampled in the run, so the tornado leaves it out."]'::jsonb, 1, 'The tornado refuses a price bar, interaction and probability: rank 1 is only the widest bar at single stated percentiles, here Total CAPEX at 16.4269.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Looking back over the tier: the honest fit of 127.2260 / 168.6738 / 252.3607 hands back 150.0000 as its 10th percentile, while the endpoints reading hands back 164.4914 for the same slot. What does that gap say about the endpoints reading?', '["The endpoints reading is the more cautious of the two, because a triangle capped at 220 can never draw an overrun beyond the stated belief of 150 / 180 / 220 million USD.", "Nothing that reaches the answer, since both triangles keep a median near 180 and the breakeven percentiles are read off the median.", "The fitted triangle double counts the tails, since its minimum and maximum lie outside a belief already stated at its extremes, stretching every draw twice over past both ends.", "The tails have vanished: the endpoints reading puts its 10th and 90th percentiles inside the stated belief, so it samples a narrower capex than was believed."]'::jsonb, 3, 'The fitted triangle''s CDF passes back through 150.0000, 180.0000 and 220.0000 exactly; the endpoints reading''s 10th percentile of 164.4914 sits inside the belief.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'A belief''s shape ratio, (50th - 10th) / (90th - 10th), must sit strictly inside 0.381966 to 0.618034. What does the engine do with ISIALA''s narrow opex belief 16 / 17 / 26, whose ratio is 0.100000?', '["Refuses the belief with an error and asks for a wider 90th percentile of opex before any iteration is run.", "Clamps it to the most left-skewed triangle there is, mode at the minimum, reports exact false and carries the note into the insight.", "Rewrites the stated median to the nearest reachable ratio and solves the base case and the tornado at that rewritten median of opex instead of 17.", "Fits it exactly by placing the mode below the minimum, since three points always determine one triangular distribution of some shape or other."]'::jsonb, 1, 'The clamped fit is 15.1886 / 15.1886 / 31.0000 with exact false; nothing refuses the belief and nothing rewrites the stated median of 17.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'ISIALA with the narrow opex belief 16 / 17 / 26 reports a base breakeven of 67.2301 and a median breakeven of 73.1740. Why must a worked reading say that the fit clamped?', '["The base case and the tornado run at the stated median of 17 while the sample draws from the clamped triangle of 15.1886 / 15.1886 / 31.0000, so one screen mixes two beliefs.", "The clamp makes the run discard every iteration that draws opex below the fitted minimum of 15.1886, so the median describes the survivors.", "A clamped fit is refitted at every seed, so the median of 73.1740 cannot be reproduced unless the note is quoted beside it.", "The note only warns about precision, since the base, the tornado and the sample all use the same clamped triangle."]'::jsonb, 0, 'Finding EC3-5: a clamped fit answers a different belief from the one stated, and only the fit note warns that the base of 67.2301 and the sample describe different opex.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Year 1 of ISIALA''s breakeven case switches tax on at 160.9994 USD per bbl, while year 2 switches it on at 18.2954. Why is year 1''s kink so much higher?', '["Year 1 produces the fewest barrels of the life while production builds up, so the same opex is spread over the smallest volume.", "Year 1 carries the full mid-year discount factor while year 2 does not, which lifts the price the first year needs to pay tax on its taxable income.", "The Breakeven Analyzer places all capex in year 1 and expenses it there, so year 1''s taxable income needs a far higher price to cross zero.", "The quick form splits capex 50/50, and year 1''s half plus a full year of royalty raises its kink above every other year''s in the twenty year profile."]'::jsonb, 2, 'After year 1 the kinks climb from 18.2954 in year 2 to 182.6642 in year 20 as the volume declines, and year 1 alone carries capex.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Iteration 1 of ISIALA''s breakeven run spends the draws 0.936239, 0.826447 and 0.952306 from mulberry32(20260829). On what?', '["Capex, efficiency and opex, since the engine separates the two cost draws so that their overruns never share one draw.", "Capex alone, the three draws averaged into one value so that no single iteration can land in a far tail.", "Capex, opex and efficiency, in that fixed order, each in its upper branch, for 226.5205, 24.4593 and 97.2265.", "The three inputs in whatever order the panel lists them, which the engine reads from the screen each run."]'::jsonb, 2, 'The order is fixed so that the same seed gives the same answer; two runs at one seed are identical, and seed 7 gives a median of 72.8475.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'ISIALA at its stated medians breaks even at 71.6277 to an NPV of zero and needs 96.5968 to reach an NPV of 100 million USD. What does the engine return for a target the 0 to 500 USD per bbl bracket cannot reach?', '["Null, because bisection needs a crossing and the NPV at the bracket top is still short of the target.", "500 USD per bbl, the bracket top, flagged so the reader knows the true breakeven lies somewhere beyond it.", "A price extrapolated past 500 from the slope of NPV against price, which is safe because NPV rises steadily with price.", "The breakeven to an NPV of zero, 71.6277, since an unreachable target falls back to the ordinary breakeven."]'::jsonb, 0, 'NPV rises with price, so if it is short of the target at 500 no price in the bracket reaches it; ISIALA''s NPV at the bracket top is 1552.6414.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Working ISIALA in the capstone order, a reader quotes the median breakeven of 73.3297 correctly. What in the order of work makes that quotation trustworthy?', '["Having quoted it to four decimals, since a figure printed to that precision could not have come from a truncated sample.", "Having run the tornado first, since its bars show whether the median was read at the right sorted index of the run.", "Having checked it sits above the base case of 71.6277, since a median above the base proves no iteration was excluded.", "Having read the exact flags and the excluded count first, since the median of a clamped belief or of a truncated sample looks the same on the page."]'::jsonb, 3, 'The mistake is doing each calculation right in the wrong order: on ISIALA all three fits are exact and 0 are excluded, and only reading those first shows it.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'In ISIALA''s worked order, beliefs, fit, base and target, run and count, percentiles and centres, tornado, at which steps would a clamped fit and an excluded iteration first become visible?', '["Both at the percentile step, where a clamped fit widens the 10th to 90th percentile spread and an exclusion narrows it.", "A clamped fit at the fit step, through the shape ratio and the exact flag; an excluded iteration at the run step, through the excluded count.", "A clamped fit at the tornado, where its bar turns lopsided, and an exclusion at the percentiles, where the base passes the 90th percentile of the run.", "Neither before the insight, which is the one place the engine reports that a fit clamped or that an iteration was excluded."]'::jsonb, 1, 'ISIALA''s shape ratios of 0.428571, 0.400000 and 0.545455 sit inside the band and the run reports excluded 0, so neither step shows a problem here.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Why does ISIALA''s worked method write the target NPV beside the base breakeven of 71.6277 USD per bbl?', '["The same case needs 96.5968 for an NPV of 100 million USD and 134.3869 for 250, so a percentile table without its target answers an unknown question.", "The target sets the seed, and the same beliefs solved at another target draw a different sample from the generator.", "The target moves only the base case and leaves the sampled percentiles at their values for a target of zero.", "The target is the discount rate under another name, and a breakeven quoted without its rate cannot be compared."]'::jsonb, 0, 'Every iteration bisects to the target, so a hurdle above zero raises the base and the whole sorted sample with it.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'In ISIALA''s worked tornado, which bar must be quoted with its input values reversed, and from which percentiles do its ends come?', '["Total CAPEX, whose widest swing of 16.4269 means its low side is taken from the fitted minimum of 127.2260 rather than from the belief as it was stated.", "Annual OPEX, whose belief 16 / 20 / 26 leans right, so both of its sides are read from the fitted triangle instead of the stated percentiles of the opex belief.", "None of the three, since every bar''s low side is its input''s 10th percentile and the checklist asks only for the swing of each bar.", "Prod. Efficiency, whose low side of -3.7306 comes from its 90th percentile of 96 percent and whose high side from its 10th percentile of 85 percent."]'::jsonb, 3, 'More efficiency lowers the breakeven, so its bar runs backwards; the order is Total CAPEX 16.4269, Annual OPEX 14.7308 and Prod. Efficiency 8.7867.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which sentence states ISIALA''s upper breakeven percentile in the words the worked method requires?', '["The engine key `p90` read aloud as P90, 85.5912 USD per bbl, the label the breakeven is stored under in the engine.", "The 90th percentile of breakeven price is 85.5912 USD per bbl, with no P-label on the price or on any input.", "The High case breakeven is 85.5912 USD per bbl, since the exceedance convention reverses on a price and a high price is the high case.", "The 90th percentile of breakeven price is 62.1713 USD per bbl, the price the breakeven meets or exceeds nine times in ten."]'::jsonb, 1, 'Three misuses are examined here: reading the key `p90` aloud as P90, putting a High case label on a price, and reading 62.1713 with the exceedance meaning. A breakeven price takes percentile words only; nine in ten iterations broke even at or under 85.5912, and 62.1713 is its 10th percentile.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'In ISIALA''s worked method the mean of 73.6242 and the base case of 71.6277 are set beside the median of 73.3297. What does the method expect of the base?', '["That it matches the median within the seed''s wobble, since a case at the stated medians gives the median answer.", "That it sits between the mean and the median, being the average of the two centres the run prints.", "That it differs from the median, being one solve at the stated medians and no statistic of the sample, and on ISIALA it is lower.", "That it moves with the seed like the two sampled centres, so it is quoted with the seed beside it."]'::jsonb, 2, 'The breakeven is no straight line in its inputs, so the output at the centre differs from the centre of the output; each centre is named separately.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'ISIALA''s 5000 iteration run at seed 20260829 reports excluded 0. In the worked method, what would any other count mean for the percentiles?', '["That they describe only the survivors, the iterations that broke even inside the bracket, and not the whole belief.", "That the engine widened the bracket past 500 USD per bbl for those iterations, so the percentiles now span a longer range.", "That they still describe the whole belief, with the excluded iterations placed at the bracket top before the sort.", "That the seed failed for those iterations and fresh draws replaced them, keeping the sample at 5000 prices."]'::jsonb, 0, 'Excluded iterations are counted and placed nowhere, which is why the count is read before any percentile; on mc_with_unreachable 55 of 120 left.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Through the Scenario Builder''s Monte Carlo at the app''s own settings, ISIALA''s NPV reads 48.7439, 81.1835 and 109.8980. Which label does 48.7439 take, and what did the panel print before the repair?', '["48.7439 is the Low case P10, as the key `p10` names it, and the old panel printed it correctly under \"P10 (Optimistic)\" all along.", "48.7439 is the 10th percentile of NPV and takes no P-label, since an NPV follows the same percentile words as a breakeven price.", "109.8980 is the Low case P90, the larger value met nine times in ten, which is what the old panel was printing and still prints.", "48.7439 is the Low case P90, stored under the key `p10`, and the old panel printed the larger 109.8980 under \"P90 (Conservative)\"."]'::jsonb, 3, 'An NPV is a quantity where more is better, so it takes exceedance labels; the option reading the key `p10` as a P-label is the mistake examined, and the old card called conservative held the larger number.'),
  ('uncertainty', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'At 5000 iterations ISIALA''s breakeven medians for seeds 1 to 10 span 72.6338 to 73.1287, and the default seed''s 73.3297 sits outside that span. What does a seed guarantee?', '["Accuracy as well as repetition, since the default seed was chosen so that its median sits at the centre of what other seeds give at 5000 iterations.", "That the run repeats exactly, and nothing about accuracy: a median printed to four decimals moves in its first decimal from seed to seed.", "That the default seed''s median is an outlier to discard, since only a median inside the span of the ten seeds is a valid one.", "Convergence, since a written seed fixes the median at the value that any larger iteration count would eventually reach as well in the limit."]'::jsonb, 1, 'The span has a range of 0.4949, and a written seed makes a result reproducible without making it the true median of the belief.'),
  ('uncertainty', 'intermediate', 'final', null, 1, 'A reviewer must say in words what ISIALA''s engineer promised by entering 220 million USD as the capex belief''s 90th percentile. Which statement is that promise?', '["No outcome costs more than 220 million USD, because the stated 90th percentile is the top of the belief and the fitted triangle ends there.", "It is the P90 capex under the exceedance meaning, a cost met or exceeded nine times in ten, and so the low capex case of the three.", "One outcome in ten costs more than 220 million USD, which is why the fitted triangle reaches on to 252.3607.", "Capex lands between 150 and 220 million USD every time, with the median of 180 marking where the triangle peaks."]'::jsonb, 2, 'A 90th percentile leaves a tenth of outcomes above it, so 150 / 180 / 220 already puts a fifth of all outcomes outside the stated numbers. Calling it P90 is the misuse this question examines: capex is an input where more is worse and takes percentile words only.'),
  ('uncertainty', 'intermediate', 'final', null, 2, 'Feed ISIALA''s capex belief of 150 / 180 / 220 straight into a triangle as minimum, mode and maximum, the engine''s old reading. What does that triangle return at 0.1 and 0.9 of its cumulative curve?', '["164.4914 and 203.2668, a belief narrower on both sides than the one the engineer stated.", "150.0000 and 220.0000, since a triangle drawn through the stated numbers hands them straight back at the matching points.", "127.2260 and 252.3607, the ends the fit places so that a tenth of the draws land beyond each stated percentile.", "182.5834 and 220.0000, because the minimum and mode move with the skew while the maximum stays at the stated top."]'::jsonb, 0, 'Under the endpoints reading nothing can cost less than 150 or more than 220, so both tails vanish and the quantiles move inward to 164.4914 and 203.2668. Only the fitted triangle 127.2260 / 168.6738 / 252.3607 returns 150.0000, 180.0000 and 220.0000.'),
  ('uncertainty', 'intermediate', 'final', null, 3, 'An engineer enters opex as 16 / 17 / 26 million USD a year, a median just 1 million USD above its 10th percentile. What comes back from the fit, and which of the three numbers survive it?', '["It refuses the belief and throws, asking for a median further from the 10th percentile before any sample is drawn.", "It moves the stated 10th percentile down until the ratio reaches the band edge of 0.381966, so that the median of 17 and the 90th percentile of 26 are both honoured exactly.", "It fits exactly, since any three ordered numbers define one triangle once the mode is allowed to sit outside the stated range.", "It clamps to the most left-skewed triangle, 15.1886 / 15.1886 / 31.0000, keeps the 10th and 90th percentiles, gives up the median, sets exact false and writes a note."]'::jsonb, 3, 'The ratio must sit strictly inside 0.381966 to 0.618034. Below the band the engine clamps, solves origin and range from the 10th and 90th percentiles, and runs on a distribution the engineer did not state, signalled only by exact false and the note.'),
  ('uncertainty', 'intermediate', 'final', null, 4, 'The fit of the narrow opex belief reports 15.1886 for both its minimum and its mode, but the mode''s position m prints as 0.000001 rather than zero. What decides that printed value?', '["The engine keeps m a hair above zero on purpose, so that the lower branch of the quantile function still carries some probability and the mode never coincides exactly with the minimum.", "Below an m of 0.1 all three checked quantiles sit on the upper branch, where the ratio stops changing with m, so floating point noise decides where the bisection stops.", "The narrow belief sits so near the band''s lower edge that the clamp lands a millionth of the range inside it.", "It is the band''s lower edge, 0.381966, rescaled into the mode''s position inside the fitted range."]'::jsonb, 1, 'Every m in that flat stretch gives exactly the edge ratio, which is why min and mode still agree to four decimals at 15.1886. The belief''s ratio of 0.100000 is far outside the band, not near its edge.'),
  ('uncertainty', 'intermediate', 'final', null, 5, 'ISIALA''s efficiency belief of 85 / 91 / 96 percent fits a triangle whose maximum is 99.9640. What keeps that maximum under 100 percent?', '["The fit caps the maximum at 100 percent and would set exact false with a note, the same shape as the clamp it applies to a median outside the reachable band.", "Only the belief: nothing in the fit or the sampler bounds efficiency, so a belief sitting nearer the top would fit and sample values past 100 percent.", "`triInvCDF` rejects any draw above 100 percent and draws again from the generator, so a triangle past 100 never books more barrels than the profile holds.", "The engine divides efficiency by 100 and clamps the result at one before it scales the production profile."]'::jsonb, 1, 'Neither the fit nor the breakeven engine bounds a belief: the closed form never inspects min or max, and triInvCDF never truncates or rejects. 99.9640 stays under 100 because the belief is centred at 91.'),
  ('uncertainty', 'intermediate', 'final', null, 6, 'In a cost summary, the column headed median shows 168.6738 million USD, the peak of ISIALA''s fitted capex triangle. What is wrong with that entry?', '["Nothing, since a triangle''s mode and median coincide and the fit only relabels the stated middle number under another name, so either can be quoted.", "The median is 182.5834, the value a triangle with a mode of 180 returns at 0.5, which the report should quote in place of both the mode and the stated number.", "The median lies below the mode on a right-skewed belief, so the report overstates the middle capex by the width of the skew between the two numbers.", "The median is the stated 180; the belief''s long tail of overruns pulls it above the mode, and the fit chose 168.6738 to honour it."]'::jsonb, 3, 'On a skewed belief the mode, the median and the stated number differ. To return a median of 180 the fit needs a mode of 168.6738; 182.5834 is the median of the endpoints triangle, a different belief.'),
  ('uncertainty', 'intermediate', 'final', null, 7, 'To confirm the capex and efficiency fits are exact, a reviewer evaluates each fitted triangle''s inverse CDF at 0.1, 0.5 and 0.9 by hand. Which branch does each evaluation need?', '["Capex, at m 0.331225, uses the lower branch at 0.1 and the upper at 0.5 and 0.9; efficiency, at m 0.599919, uses the lower at 0.1 and 0.5 and the upper only at 0.9.", "Every check at 0.5 or below uses the lower branch and every check above uses the upper, whatever the mode''s position.", "Capex and efficiency split the same way, lower at 0.1 and upper at 0.5 and 0.9, since both are exact fits.", "All three checks use the lower branch, because the fitted triangle is built from its minimum upward."]'::jsonb, 0, 'The lower branch serves u up to m and the upper branch u above it, so efficiency''s m of 0.599919 puts its median check on the lower branch. A check that pushes all three points through one formula gets at least one of them wrong.'),
  ('uncertainty', 'intermediate', 'final', null, 8, '`mulberry32(20260829)` opens 0.936239, 0.826447, 0.952306, 0.732031, 0.064278, 0.391443. Which draws make iteration 2 of ISIALA''s breakeven run, and where do they land?', '["Capex takes 0.826447, the second draw, on the upper branch, since iteration k starts at draw k, then iteration 2 continues with the next two draws for opex and efficiency.", "Capex takes 0.732031 on the lower branch, because a draw below 0.9 cannot reach past the stated 90th percentile of 220.", "Capex takes 0.732031 on the upper branch, opex takes 0.064278 on the lower branch below the stated 16, and efficiency takes 0.391443 below the stated median of 91.", "Opex takes 0.732031 and capex 0.064278, because the order follows the variables as they are entered on the input screen."]'::jsonb, 2, 'Draws belong to positions: iteration 1 owns draws 1 to 3 and iteration 2 draws 4 to 6, always capex, opex, efficiency. Opex''s 0.064278 is below its F(mode) of 0.233597 and below 0.1, so it lands between 13.3201 and the stated 10th percentile.'),
  ('uncertainty', 'intermediate', 'final', null, 9, 'mc_with_unreachable excludes 55 of its 120 iterations. A reviewer rebuilding it by hand drops the excluded iterations from the count before assigning draws. What goes wrong?', '["Every later iteration slides onto the wrong draws, because an excluded iteration consumes its three draws before its solve comes back empty.", "Nothing, since an excluded iteration never draws at all and the generator moves straight on to the next iteration that can break even under the bracket top.", "Only the excluded iterations are affected, since the generator is reseeded for each iteration from the run seed and the iteration number, so no draw is shared.", "The percentiles move, because the engine sets each excluded iteration to 500 USD/bbl and sorts it into the top of the sample."]'::jsonb, 0, 'The three draws per iteration are taken before the solve, so exclusion never shifts later draws. The 55 excluded iterations are not placed anywhere either: they are absent from every statistic except the count.'),
  ('uncertainty', 'intermediate', 'final', null, 10, 'ISIALA''s breakeven median is 73.3297 USD/bbl at the default seed over 5000 iterations, and two runs at that seed match value for value. Across seeds 1 to 10 at the same count the medians span 72.6338 to 73.1287. What should a report take from this?', '["73.3297 is the accurate median, because a matching rerun at the default seed validates it and the other ten seeds are unvalidated samples of the same inputs.", "The engine is unstable across seeds and should be fixed, since one set of inputs ought to produce a single median at any seed.", "Report whichever seed reads best, since each of the eleven results reproduces exactly and the written seed makes any one of them defensible in front of a board.", "The seed makes 73.3297 repeatable and says nothing about accuracy: it sits above all ten other medians, and the first decimal moves from seed to seed."]'::jsonb, 3, 'A seed buys reproducibility, not accuracy. The range across the ten seeds is 0.4949, so the honest reading is the spread; seed shopping is reproducible without being representative.'),
  ('uncertainty', 'intermediate', 'final', null, 11, 'ISIALA''s breakeven is run at the default seed for 1000, then 5000, then 20000 iterations, and the median rises and then falls back. What is true of those three runs?', '["Each count draws a fresh stream from the seed, so the three runs share no iterations and cannot be compared with one another at all.", "The median converges steadily as iterations grow, so 73.0302 at 20000 is within a known tolerance of the true median.", "The longer runs begin with exactly the shorter runs'' iterations and add more, so only the sorted positions move, and the median wanders instead of creeping toward one value.", "The insight warns that the 1000 iteration run is too small, which is why its median sits below the other two."]'::jsonb, 2, 'Same seed, same draws in the same order: the count changes only the size of the sample the percentiles are read from. The reproducibility sentence reads the same at 100 iterations as at 20000, so the seed never reports its own wobble.'),
  ('uncertainty', 'intermediate', 'final', null, 12, 'A spreadsheet sampler keeps only the formula that climbs from the minimum toward the mode and applies it to every u on ISIALA''s capex triangle. What happens to iteration 1''s capex draw of 0.936239?', '["Nothing, since the two branches meet at the mode and give the same value for any draw on either side of it.", "It returns less than the true 226.5205, pulling every upper-branch draw toward the middle and shrinking the expensive tail, the endpoints error by another door.", "It returns more than the true value, because the lower formula grows with the square root of the whole range, stretching the tail of overruns out past the fitted maximum of 252.3607.", "It returns the stated 90th percentile of 220, since the lower branch reads the belief instead of the fitted triangle."]'::jsonb, 1, 'The lower formula is valid only up to F(mode), 0.331225 for capex. Past the mode it always undershoots, so the sample loses expensive capex just as the minimum, mode and maximum reading did.'),
  ('uncertainty', 'intermediate', 'final', null, 13, 'Iteration 1 draws a capex of 226.5205 million USD, above the stated 90th percentile of 220. Is the sample wrong?', '["No: its draw of 0.936239 is above 0.9, the exact fit makes the fitted 90th percentile equal 220, and the fitted maximum of 252.3607 leaves room.", "Yes: 220 is the top of the stated belief, so any sampled capex above it shows the sampler ignored the fitted triangle and drew from outside its range.", "No, but only because the first draw of any run is taken from the top tenth of the generator to seed the tail.", "Yes: a draw of 0.936239 belongs on the lower branch, which climbs from the minimum and would have kept the value inside the stated range of 150 to 220."]'::jsonb, 0, 'A tenth of capex draws should land above 220. The draw 0.936239 exceeds F(mode) of 0.331225, so it takes the upper branch and lands between the fitted 90th percentile and the fitted maximum.'),
  ('uncertainty', 'intermediate', 'final', null, 14, 'ISIALA''s quick screening case is worth 81.0464 million USD at 70 USD/bbl, yet its base breakeven is 71.6277 USD/bbl. Which reading is right?', '["The screening NPV, since a field worth 81.0464 million USD at 70 USD/bbl must break even well below 70, so the breakeven engine has a defect.", "Both, once the breakeven engine''s year-end discounting is converted to the screening engine''s mid-year convention.", "Both: they are different cases; the breakeven case puts all capex in year 1, charges a flat 20 million USD a year and sells 0.91 of the volume, and its NPV at 70 USD/bbl is -6.5653.", "The breakeven, since 71.6277 is the median of the sampled prices and the screening NPV ignores the uncertainty in the inputs."]'::jsonb, 2, 'Both engines discount mid-year; the gap is the case each builds. The quick form splits capex 50/50 and charges 2.5 million USD fixed plus 13 USD/bbl variable opex, so 71.6277 says nothing about where 81.0464 falls to zero.'),
  ('uncertainty', 'intermediate', 'final', null, 15, 'Why does `solveBreakevenPrice` bisect a 0 to 500 USD/bbl bracket instead of using Newton''s method?', '["NPV falls briefly with price just above each kink, where a year starts paying tax, and only bisection can step over such a local dip without settling on the wrong one of several crossings.", "The slope of NPV against price changes abruptly wherever a year starts paying tax, and bisection needs only that NPV never falls with price and the answer lies in the bracket.", "Bisection reports its tolerance and step count beside the price, which Newton''s method cannot do for a ledger this long.", "Newton''s method would need more NPV evaluations, each a full twenty year ledger, and bisection is the cheaper search."]'::jsonb, 1, 'Crossing a kink bends the line to a shallower slope but never turns it down or makes it jump. Bisection spends more evaluations than a cleverer method, is never wrong about which side the answer is on, and reports only a price.'),
  ('uncertainty', 'intermediate', 'final', null, 16, 'At ISIALA''s base breakeven of 71.6277 USD/bbl the year 12 and year 13 tax switch-on prices sit either side of the price. Which years hand over tax there?', '["Years 1 to 12, since year 1 has the largest volume and the kinks are read in calendar order from 2027 up to the price.", "Years 13 to 20, since a year pays tax once the price sits below its kink and the late years have the highest kinks.", "Every year from 2029 on, because the quick form splits the capex over 2027 and 2028 and expenses each half in its own year.", "Years 2 to 12; year 1, whose kink is 160.9994 because it carries all the capex, and years 13 to 20 pay none."]'::jsonb, 3, 'A year pays tax when the price is above its kink. At 71.6277 that is 2028, at 18.2954, through 2038; years 13 to 20 also lose money at that price and are charged in full, because the engine has no economic limit.'),
  ('uncertainty', 'intermediate', 'final', null, 17, 'ISIALA''s breakeven engine NPV is -6.5653 at 70 USD/bbl and 33.6477 at 80. A straight line between them reads a slightly higher breakeven than the solved 71.6277. Why?', '["Year 13''s kink at 74.6504 sits inside the interval, and below it NPV climbs more steeply, so the true crossing comes earlier than the line.", "Bisection stops before the bracket closes and understates the price, so the interpolated value is the more precise of the two and the solved price should be corrected.", "Above 74.6504 NPV climbs more steeply than below it, as each taxed year adds more, which drags the straight line''s crossing to the left of the curve''s.", "The table rounds each NPV to four decimals, which moves the interpolated crossing by about the gap between the two."]'::jsonb, 0, 'Crossing a kink hands 35 percent of that year''s extra revenue after royalty to tax and bends the line shallower. The curve is steeper on the left piece, so it reaches zero sooner than the chord between 70 and 80.'),
  ('uncertainty', 'intermediate', 'final', null, 18, 'Year 1 of ISIALA''s breakeven case expenses all 180 million USD of capex. Is that deduction worth 35 percent of 180 million USD at any price?', '["Yes: immediate expensing shelters the whole capex in the year it is spent, whatever that year''s revenue happens to be.", "Yes, spread over two years: the capex is split 50/50 and each half is deducted against its own year''s revenue.", "No: below 160.9994 USD/bbl year 1''s income cannot absorb it, the unsheltered part is lost with no carry forward, and an engine with a carry forward would report a lower breakeven.", "No: the deduction is worth 35 percent only above 182.6642 USD/bbl, the highest kink, where every year pays tax."]'::jsonb, 2, 'Tax is charged only on a positive base, year by year, and the breakeven engine refuses to carry a loss forward. Year 1''s kink is 160.9994, so at the breakeven of 71.6277 year 1 pays no tax and much of the deduction shelters nothing.'),
  ('uncertainty', 'intermediate', 'final', null, 19, 'ISIALA''s breakeven case is worth 1552.6414 million USD at 500 USD/bbl. What does the solver return for a target above that, and for a case that would break even at just over 500?', '["500 for both, the top of the bracket, flagged so that a reader can tell a near miss from a case that never breaks even at any price.", "Null for both, since the top check fails first and the solver refuses to widen its bracket, so the two look exactly alike.", "Null for the first, and a price for the second, found by doubling the bracket to 1000 USD/bbl and searching again until the target is reached.", "The price at which NPV comes closest to the target, reported with a note in the insight that the target itself was not met inside the bracket."]'::jsonb, 1, 'The solver prices the top of the bracket before it searches and returns null if NPV there is below the target. A price of 500 USD/bbl is the edge of its world, whether the miss is small or total.'),
  ('uncertainty', 'intermediate', 'final', null, 20, 'A board paper headed ISIALA breakeven quotes 96.5968 USD/bbl, copied from a run whose target NPV was set to 100 million USD. What has the paper done?', '["Nothing wrong, since the target NPV only moves the discount rate the engine uses, and the answer is still a breakeven price at that higher rate of return.", "Added 100 million USD of capex to the case, which the engine discounts and expenses in year 1 alongside the 180 before it solves for the price.", "Quoted the 90th percentile of breakeven price, since a hurdle of 100 million USD sits at the pessimistic end of the sample.", "Reported a hurdle price as the breakeven, quietly demanding 12 percent plus 100 million USD of present value; the plain breakeven is 71.6277."]'::jsonb, 3, 'A hurdle is money at the discount rate: the factors stay as they are and the target asks for a fixed sum. Raising the rate would reweigh every year, and extra capex would enter year 1''s tax base; a target does neither.'),
  ('uncertainty', 'intermediate', 'final', null, 21, 'mc_seed_7 and mc_target_250_seed_7 share seed 7 and 300 iterations; their medians read 179.2190 and 214.9766 USD/bbl. Why is comparing them fair?', '["The same seed gives the same draws, so every iteration has the same sampled capex, opex and efficiency in both, and only the target moved.", "The seed forces each run to read its percentiles from the same sorted indices, which is what makes any two runs comparable.", "It is fair only for the medians, since the draws differ and the 10th and 90th percentiles respond to a different sample.", "It is not fair, since a target of 250 raises the discount rate and changes every draw''s weight in the sample."]'::jsonb, 0, 'Each iteration''s price moved up and the whole distribution with it. The base case moves the same way, from 175.1500 to 210.4257, matching solve_base_target_250.'),
  ('uncertainty', 'intermediate', 'final', null, 22, 'solve_free_project_zero, a case with no capex and no opex, returns 0.0000 USD/bbl. How should it be read?', '["As a failed solve, since a spreadsheet null reads as 0 and the engine returns 0.0000 whenever it cannot find a crossing inside the 0 to 500 bracket.", "As a free price for a project that cannot break even, the same result solve_zero_production_null returns for a case with no production at all.", "As the correct breakeven: NPV at 0 USD/bbl is already non-negative, so every midpoint becomes the high end and the bracket collapses onto 0.", "As the low end of the bracket, reported because bisection ran out of steps before the midpoint could move."]'::jsonb, 2, 'The engine returns null when no price reaches the target, as solve_zero_production_null does, so 0.0000 is a real answer. The opposite mistake is letting a spreadsheet turn a null into 0, which reads a project that cannot break even as free.'),
  ('uncertainty', 'intermediate', 'final', null, 23, 'ISIALA''s breakeven run has 5000 iterations and excludes none. Which sorted values does the engine report as its 10th percentile, median and 90th percentile?', '["The averages of the two values either side of indices 500, 2500 and 4500, since those positions fall on whole numbers on an even sample length.", "The single sorted values at indices 500, 2500 and 4500, counting from zero, so each reported price is one an iteration actually produced.", "Interpolated values between neighbouring prices, placed where the S-curve height reaches exactly a tenth, a half and nine tenths of the sample.", "The values one index below each of those positions, because the S-curve places index i at height (i + 1) / n."]'::jsonb, 1, 'The breakeven rule is sorted[min(n - 1, floor(q n))]: floor means no averaging and no interpolation. Averaging two neighbours when n x q is whole on an even length is the screening engine''s rule, a different one.'),
  ('uncertainty', 'intermediate', 'final', null, 24, 'An analyst writes ''P90 breakeven 62.1713 USD/bbl, our conservative price'' for ISIALA. What is wrong?', '["Only the label: 62.1713 is correctly the conservative breakeven, and the sentence should call it the 10th percentile of breakeven price.", "Nothing, since under the exceedance meaning the breakeven meets or exceeds 62.1713 nine times in ten, which is what P90 asserts.", "The number: the P90 breakeven should be 85.5912, since P90 and the engine key `p90` name the same quantity.", "Two things: a breakeven price takes percentile words only, and 62.1713 is its 10th percentile, the least conservative of the three; the cautious figure is the 90th percentile, 85.5912."]'::jsonb, 3, 'Defending P90 on a price applies the exceedance meaning to a quantity where more is worse, and mapping P90 onto the key `p90` is the other misuse; both are the mistakes this question examines. Keeping 62.1713 as the conservative price is the third: it is the 10th percentile, the least conservative of the three. The sentence to write is: the 90th percentile of ISIALA''s breakeven price is 85.5912 USD/bbl.'),
  ('uncertainty', 'intermediate', 'final', null, 25, 'mc_with_unreachable reports 397.3404, 449.5729 and 486.6757 USD/bbl as its 10th percentile, median and 90th percentile, excluding 55 of 120 iterations, while its base case breaks even at 498.0372. What does the base above the 90th percentile show?', '["The percentiles describe survivors only: every excluded iteration needed a price above 500, so the whole sample''s median lies above 449.5729.", "The base case is a single solve at the stated medians, which always sits above the sample''s 90th percentile whenever the beliefs are skewed toward overruns.", "The excluded iterations were set to 500 USD/bbl and sorted into the top of the sample, which drags the reported percentiles upward toward the base.", "The run is tight and well behaved, and the base simply reflects a capex belief whose median sits near its 90th percentile."]'::jsonb, 0, 'On ISIALA''s complete sample the base of 71.6277 sits between the 10th percentile and the median. Here it sits past the top because the dear draws left and the cheap ones stayed, and the printed count is the only evidence of the truncation.'),
  ('uncertainty', 'intermediate', 'final', null, 26, 'ISIALA''s breakeven mean is 73.6242 USD/bbl against a median of 73.3297. Why does the mean sit higher?', '["The mean includes the base case of 71.6277 as one extra value, which the sorted median never counts.", "The efficiency triangle leans toward high efficiency, and every high-efficiency draw lifts the breakeven above the middle.", "The right tail is longer: the capex and opex triangles, 127.2260 / 168.6738 / 252.3607 and 13.3201 / 17.4160 / 30.8541, have low modes and long upper reaches, so the dearest draws pull a few prices far up.", "Excluded iterations are counted into the mean at 500 USD/bbl while the median reads only the survivors."]'::jsonb, 2, 'Mean minus median is 0.2944, and the sample runs from 50.7415 to 107.6755, further above the median than below. mc_with_unreachable shows the reverse, a mean of 446.8432 under its median of 449.5729, because its expensive tail was cut at the bracket.'),
  ('uncertainty', 'intermediate', 'final', null, 27, 'The breakeven engine reads ISIALA''s median at sorted index 2500 of 5000, and the S-curve draws that same price 0.500200 of the way up. Why not exactly one half?', '["The seed offsets every height by one draw, so a different seed would put the median at a round half.", "The heights are computed on the surviving iterations, and ISIALA''s excluded iterations shrink n below 5000.", "The S-curve is downsampled to 50 points with a last probability of 98.0000, so its heights are rounded to the kept points.", "The curve places index i at (i + 1) / n while the percentile rule reads index floor(q n), two conventions a step apart."]'::jsonb, 3, 'The first point sits one step off zero and the last reaches one, so reading the curve at exactly a half lands one step left of the reported median. The downsampled curve ending at 98.0000 is the Scenario Builder''s, another engine.'),
  ('uncertainty', 'intermediate', 'final', null, 28, 'A slide redraws ISIALA''s breakeven S-curve as one minus its cumulative height, an exceedance curve, and keeps 85.5912 USD/bbl marked at nine tenths. What does that price become on the slide?', '["The same statement in other words, since exceedance and cumulative readings agree at the 90th percentile of any sample.", "A price the breakeven exceeds nine times in ten, the opposite of what the run found.", "The P90 breakeven under the exceedance meaning, which is the conservative price the sanction note should quote.", "The highest price in the sample, since an exceedance curve is read downward from the top of the sorted list."]'::jsonb, 1, 'The height is the probability of a breakeven at or under the price, so nine in ten iterations broke even at or under 85.5912. Calling it P90 applies the exceedance meaning to a price where more is worse, the misuse this question examines.'),
  ('uncertainty', 'intermediate', 'final', null, 29, 'ISIALA''s 5000 breakeven prices run from 50.7415 to 107.6755 USD/bbl. Why are those two not the range to quote?', '["Each is a single iteration, one lucky or unlucky trio of draws, while the 10th and 90th percentiles each have hundreds of prices beyond them.", "They are the fitted minimum and maximum of the breakeven distribution, which the engine solves from the triangles and reports only for plotting.", "They are the prices at the S-curve''s first and last points, which the downsample drops before the chart is drawn.", "They are true bounds, since the sampler cannot draw beyond its fitted triangles, but they are too wide to be useful in a report to a sanction meeting."]'::jsonb, 0, 'The S-curve reads zero under 50.7415 and one past 107.6755 only because these draws did not reach further, which says nothing about how low or high ISIALA''s breakeven can go.'),
  ('uncertainty', 'intermediate', 'final', null, 30, 'Capex and opex at their stated 90th percentiles with efficiency at its stated 10th make one pessimistic corner. How does that corner relate to ISIALA''s 90th percentile of breakeven price, 85.5912 USD/bbl?', '["It is the same number, since the 90th percentile of the price is by definition the breakeven with each input at its own pessimistic stated percentile.", "It is found by adding the three tornado high sides to the base case of 71.6277, which is how the engine builds its 90th percentile of breakeven price.", "It is a different quantity: three independent draws land beyond all three of those values together far less often than one iteration in ten.", "It sits below 85.5912, because each input at its stated percentile is milder than the fitted ends the sample reaches."]'::jsonb, 2, 'The 90th percentile is read off the sorted sample; the tornado swings one variable at a time and never looks at the sample. Neither the corner nor a sum of bars is a percentile of the price.'),
  ('uncertainty', 'intermediate', 'final', null, 31, 'A reader copies 9.4067 off the high end of ISIALA''s capex bar into a table of prices. What kind of number has been copied?', '["The breakeven price at the 90th percentile of capex, read straight off the chart as a price in USD/bbl and quoted beside the base case.", "A distance from the sample median of 73.3297, since the tornado measures each bar from the centre of the 5000 iteration run it sits beside.", "The share of the 5000 iterations whose breakeven moved when capex was drawn above its stated median, expressed in percentage points.", "A distance in USD/bbl from the base breakeven of 71.6277, at capex''s 90th percentile of 220 with the other two at their medians."]'::jsonb, 3, 'Every low side and high side is a distance from 71.6277. Quoting 9.4067 as a price, or measuring it from 73.3297, mixes two anchors.'),
  ('uncertainty', 'intermediate', 'final', null, 32, 'The efficiency bar, third on ISIALA''s tornado, ends at -3.7306 and 5.0561. Which efficiency produced each end?', '["The low side comes from the 10th percentile of 85 percent and the high side from the 90th percentile of 96, the same order as on every other bar.", "The low side comes from the 90th percentile efficiency of 96 percent and the high side from the 10th percentile of 85 percent.", "The low side comes from the fitted minimum of 80.1459 and the high side from the fitted maximum of 99.9640, the triangle''s two ends.", "Both ends come from the fitted mode of 92.0352, shifted by half the swing to either side of it so that the bar is centred on the mode."]'::jsonb, 1, 'Efficiency sits in the denominator of the kink price beside the volume, so more efficiency lowers the breakeven. Low side and high side describe the price, never which percentile stands behind it.'),
  ('uncertainty', 'intermediate', 'final', null, 33, 'A sanction note turns ISIALA''s widest tornado bar, a swing of 16.4269 USD/bbl, into a symmetric band around the base breakeven. What does that band hide?', '["The bar is lopsided, -7.0202 against 9.4067, because 220 sits further above 180 than 150 sits below it, so the overrun hurts more than the saving helps.", "Nothing of substance, since a tornado bar is symmetric about the base by construction: each side is the same step in the belief, so the halves equal the two printed sides.", "That the swing is measured to the fitted ends 127.2260 and 252.3607, which the stated percentiles would halve.", "That the swing belongs to the 90th percentile of breakeven price and not to the base case the note is quoting."]'::jsonb, 0, 'Half the swing each way puts the low end too low and the high end too short. The fitted ends never enter the chart; only the stated 10th and 90th percentiles do.'),
  ('uncertainty', 'intermediate', 'final', null, 34, 'ISIALA with the narrow opex belief 16 / 17 / 26 reports a base breakeven of 67.2301 and sample percentiles of 62.0843, 73.1740 and 85.4599 USD/bbl. Which belief does each number come from?', '["All of them use the clamped triangle, since once the fit clamps the engine replaces the stated median with the fitted one everywhere.", "All of them use the stated belief, since the clamp only changes the note in the insight and never the distribution sampled.", "The base uses the fitted mode of 15.1886 and the percentiles use the stated belief, which is why the base sits below the median.", "The base and the tornado use the stated median of 17; the percentiles come from the clamped triangle 15.1886 / 15.1886 / 31.0000, whose median sits higher, so one screen mixes two beliefs."]'::jsonb, 3, 'The base case and the tornado read the stated median while the sample draws from the fitted triangle. When the fit clamps, the fitted median is not the stated one, and only exact false and the fit note warn.'),
  ('uncertainty', 'intermediate', 'final', null, 35, 'On the narrow opex belief the bars read Total CAPEX -7.0493 and 9.4442, Annual OPEX -1.4602 and 13.2707, Prod. Efficiency -3.5016 and 4.7457. How does opex rank?', '["It ranks last on every sort, since its low side of -1.4602 shows the belief barely moves the price in either direction at all.", "It ranks first on every sort, since a cost charged in every year of the life always outweighs capex that is spent only once.", "It leads a sort by high side and trails both others in a sort by low side; the swing folds both directions into one width.", "It cannot be ranked, since a clamped fit sets exact false and the engine drops that bar from the chart until the belief is widened."]'::jsonb, 2, 'A step down to 16 barely moves the price and the reach up to 26 moves it a great deal. The bar is as lopsided as the belief 16 / 17 / 26 behind it.'),
  ('uncertainty', 'intermediate', 'final', null, 36, 'On mc_with_unreachable, whose base breaks even at 498.0372 USD/bbl, the tornado prints every high side as 0.0000 beside low sides of -80.7218, -6.7689 and -26.2125. How should a high side of 0.0000 be read?', '["As a side the engine never placed, finding B1, which is still open: a missing side prints as a zero that looks exactly like an input that does not matter.", "As an input with no upward effect, since at a base this close to the bracket top no input can raise the price any further.", "As a result the repairs made before this course removed, so that on today''s engine a 0.0000 high side means the variable moved the breakeven price by less than a cent.", "As the price capped at the bracket top of 500, reported as a distance of zero because the solve stopped at the edge."]'::jsonb, 0, 'B1 is not repaired: every high side of mc_with_unreachable still reads 0.0000. The base sits just short of the 500 USD/bbl bracket top, and a zero there is an absence printed as a number.'),
  ('uncertainty', 'intermediate', 'final', null, 37, 'ISIALA''s two sensitivity charts disagree about opex: the screening engine''s 0.7 to 1.3 chart puts OPEX last, while the breakeven tornado puts Annual OPEX second. What explains the disagreement?', '["The screening engine discounts at year end and the breakeven engine mid-year, which weighs every year''s opex differently in the two charts.", "The screening bar scales fixed opex of 2.5 million USD a year only, while the tornado swings the whole 20 million USD a year belief.", "One of the two is wrong, since one field has one sensitivity to opex whatever chart is used to show it, and the tornado is the newer engine.", "The tornado samples opex from its fitted triangle, so its bar reaches out to the fitted maximum of 30.8541 where the screening bar stops at 1.3."]'::jsonb, 1, 'Different cases, different quantities and different scaling rules, so neither ranking carries across. The tornado swings stated percentiles, never fitted ends.'),
  ('uncertainty', 'intermediate', 'final', null, 38, 'ISIALA''s fitted modes are 168.6738 for capex, 17.4160 for opex and 92.0352 for efficiency. What role do they play in the tornado''s base of 71.6277 USD/bbl?', '["They are the base, since the most likely value of each input gives the most likely breakeven price.", "They set the base for capex and opex, the two right-skewed costs, while efficiency uses its stated median of 91 because its triangle leans the other way from the two costs.", "None: the base is solved at the stated medians, capex 180, opex 20 and efficiency 0.91, and a base built from the modes would solve a different project.", "They move the base whenever the seed changes, because the modes are refitted from each run''s sample."]'::jsonb, 2, 'The fit exists to pass a triangle through three points for sampling. The base is one solve, unchanged at any seed, and every bar is a distance from it.'),
  ('uncertainty', 'intermediate', 'final', null, 39, 'A capstone reading quotes 73.3297 as ISIALA''s median breakeven, correctly, without reading the exact flags or the excluded count. Why is that incomplete?', '["It is complete, since a correct median proves the fit and the run were read correctly on the way to it.", "The median must be quoted as P50, because a graded breakeven reading follows the exceedance convention.", "The excluded count is printed only when a fit clamps, so reading the exact flags first is enough to cover both.", "A median of a clamped belief or of a truncated sample would look the same on the page, and the exact flag at the fit step and the excluded count at the run step are where either shows."]'::jsonb, 3, 'Work in the engine''s order: beliefs, fit, base and target, run and count, percentiles and centres, tornado. A P50 on a breakeven price is the label misuse this course refuses, since a price takes percentile words.'),
  ('uncertainty', 'intermediate', 'final', null, 40, 'Through the Scenario Builder''s Monte Carlo at seed 20260829 ISIALA''s NPV reads 48.7439, 81.1835 and 109.8980 million USD, while its breakeven run reads 62.1713, 73.3297 and 85.5912 USD/bbl. How do the labels differ?', '["The NPV takes exceedance labels, Low case P90 48.7439 under the key `p10`; the breakeven price takes percentile words, with 85.5912 its 90th percentile.", "Both take exceedance labels under the same definition, so the NPV''s P90 is 109.8980 and the breakeven''s P90 is 85.5912, each read straight off its own `p90` key.", "Both take percentile words, since a 90th percentile means the same thing on a price as it does on an NPV.", "The NPV''s conservative card is 109.8980, as the shipped panel printed it, and the breakeven''s conservative price is 62.1713."]'::jsonb, 0, 'An NPV is an outcome where more is better, so P90 is its low case; reading P90 off the `p90` key, or labelling a price, is the misuse examined here. Giving the NPV percentile words drops the exceedance label it needs, and the panel that shipped before the repair printed 109.8980 under ''P90 (Conservative)''.'),
  ('uncertainty', 'intermediate', 'final', null, 41, 'On the same 1000 Scenario Builder NPVs for ISIALA, the screening rule gives a 10th percentile of 48.7439 and the breakeven rule gives 48.8335. Which is right?', '["48.8335, since the screening rule''s averaging is a defect the breakeven engine was written to repair.", "Both, by their own definitions: the screening rule averages two neighbours when n x q is whole on an even length, and the breakeven rule takes sorted[min(n - 1, floor(q n))].", "48.7439, since the breakeven rule is only valid for prices and gives a biased percentile on an NPV.", "Neither, since the difference shows the seed was not held fixed between the two readings of the sample."]'::jsonb, 1, 'At n of 1000, n x 0.1 is 100, a whole number, so the screening rule averages and the breakeven rule reads one sorted value. Two rules live in one module, so a quoted percentile should name its rule.'),
  ('uncertainty', 'intermediate', 'final', null, 42, 'mc_default_seed_300 reports a base of 175.1500, a median of 178.1754 and a mean of 180.0854 USD/bbl, in the same order as ISIALA. Why does the base at the stated medians not equal the median of the run?', '["The base is solved at the fitted modes, which sit below the stated medians on right-skewed cost beliefs.", "The base uses a different seed from the run, so its draws differ from the sample the median is read from.", "The breakeven is no straight line in its inputs: efficiency scales the barrels and tax switches on year by year at its own kink, so skewed beliefs pushed through it move the centre.", "The run''s bisection stops at a looser tolerance than the single base solve, which lifts every sampled price slightly."]'::jsonb, 2, 'Plugging the medians in does not give the median answer. The base is one solve with no sampling at all, and on ISIALA it sits at 71.6277 under a median of 73.3297.');
